/* DAWAH X — ahmad, অধ্যায় 4 · খণ্ড 4 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][4]=[[601,601,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَامِرٌ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشَرَةً آكِلَ الرِّبَا ‏ ‏وَمُوكِلَهُ وَكَاتِبَهُ وَشَاهِدَيْهِ ‏ ‏وَالْحَالَّ ‏ ‏وَالْمُحَلَّلَ ‏ ‏لَهُ وَمَانِعَ ‏ ‏الصَّدَقَةِ ‏ ‏وَالْوَاشِمَةَ ‏ ‏وَالْمُسْتَوْشِمَةَ ‏","","",""],[602,602,"","","‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏وَأَنَا حَدِيثُ السِّنِّ قَالَ قُلْتُ تَبْعَثُنِي إِلَى قَوْمٍ يَكُونُ بَيْنَهُمْ أَحْدَاثٌ وَلَا عِلْمَ لِي ‏ ‏بِالْقَضَاءِ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ ‏ ‏سَيَهْدِي لِسَانَكَ وَيُثَبِّتُ قَلْبَكَ ‏ ‏قَالَ ‏ ‏فَمَا شَكَكْتُ فِي قَضَاءٍ بَيْنَ اثْنَيْنِ بَعْدُ ‏","","",""],[603,603,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا وَجِعٌ وَأَنَا أَقُولُ اللَّهُمَّ إِنْ كَانَ أَجَلِي قَدْ حَضَرَ فَأَرِحْنِي وَإِنْ كَانَ آجِلًا فَارْفَعْنِي وَإِنْ كَانَ ‏ ‏بَلَاءً ‏ ‏فَصَبِّرْنِي قَالَ ‏ ‏مَا قُلْتَ فَأَعَدْتُ عَلَيْهِ فَضَرَبَنِي بِرِجْلِهِ فَقَالَ مَا قُلْتَ قَالَ فَأَعَدْتُ عَلَيْهِ فَقَالَ اللَّهُمَّ عَافِهِ ‏ ‏أَوْ اشْفِهِ ‏ ‏قَالَ ‏ ‏فَمَا اشْتَكَيْتُ ذَلِكَ الْوَجَعَ بَعْدُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنْتُ شَاكِيًا فَمَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ اللَّهُمَّ عَافِهِ اللَّهُمَّ اشْفِهِ فَمَا اشْتَكَيْتُ ذَلِكَ الْوَجَعَ بَعْدُ ‏","","",""],[604,604,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ عَلَى ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَا وَرَجُلَانِ فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْضِي ‏ ‏حَاجَتَهُ ثُمَّ يَخْرُجُ فَيَقْرَأُ الْقُرْآنَ وَيَأْكُلُ مَعَنَا اللَّحْمَ وَلَا يَحْجِزُهُ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏يَحْجُبُهُ ‏ ‏مِنْ الْقُرْآنِ شَيْءٌ لَيْسَ الْجَنَابَةَ ‏","","",""],[605,605,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَيْرُ نِسَائِهَا ‏ ‏مَرْيَمُ بِنْتُ عِمْرَانَ ‏ ‏وَخَيْرُ نِسَائِهَا ‏ ‏خَدِيجَةُ ‏","","",""],[606,606,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحِيمِ الْكِنْدِيِّ ‏ ‏عَنْ ‏ ‏زَاذَانَ أَبِي عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏فِي ‏ ‏الرَّحْبَةِ ‏ ‏وَهُوَ ‏ ‏يَنْشُدُ ‏ ‏النَّاسَ مَنْ شَهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏غَدِيرِ خُمٍّ ‏ ‏وَهُوَ يَقُولُ مَا قَالَ فَقَامَ ثَلَاثَةَ عَشَرَ رَجُلًا فَشَهِدُوا أَنَّهُمْ سَمِعُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏مَنْ كُنْتُ ‏ ‏مَوْلَاهُ ‏ ‏فَعَلِيٌّ ‏ ‏مَوْلَاهُ ‏","","",""],[607,607,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَاللَّهِ إِنَّهُ مِمَّا ‏ ‏عَهِدَ ‏ ‏إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏لَا يُبْغِضُنِي إِلَّا مُنَافِقٌ وَلَا يُحِبُّنِي إِلَّا مُؤْمِنٌ ‏","","",""],[608,608,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏أَنْبَأَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏جَهَّزَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاطِمَةَ ‏ ‏فِي ‏ ‏خَمِيلٍ ‏ ‏وَقِرْبَةٍ وَوِسَادَةِ ‏ ‏أَدَمٍ ‏ ‏حَشْوُهَا لِيفُ ‏ ‏الْإِذْخِرِ ‏","","",""],[609,609,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏نُعَيْمُ بْنُ حَكِيمٍ الْمَدَائِنِيُّ ‏ ‏عَنْ ‏ ‏أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ أَنَا وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَتَيْنَا ‏ ‏الْكَعْبَةَ ‏ ‏فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْلِسْ وَصَعِدَ عَلَى ‏ ‏مَنْكِبَيَّ ‏ ‏فَذَهَبْتُ لِأَنْهَضَ بِهِ فَرَأَى مِنِّي ضَعْفًا فَنَزَلَ وَجَلَسَ لِي نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ اصْعَدْ عَلَى ‏ ‏مَنْكِبَيَّ ‏ ‏قَالَ فَصَعِدْتُ عَلَى ‏ ‏مَنْكِبَيْهِ ‏ ‏قَالَ فَنَهَضَ بِي قَالَ فَإِنَّهُ يُخَيَّلُ إِلَيَّ أَنِّي لَوْ شِئْتُ لَنِلْتُ ‏ ‏أُفُقَ ‏ ‏السَّمَاءِ حَتَّى صَعِدْتُ عَلَى ‏ ‏الْبَيْتِ ‏ ‏وَعَلَيْهِ تِمْثَالُ ‏ ‏صُفْرٍ ‏ ‏أَوْ نُحَاسٍ فَجَعَلْتُ أُزَاوِلُهُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ وَبَيْنَ يَدَيْهِ وَمِنْ خَلْفِهِ حَتَّى إِذَا اسْتَمْكَنْتُ مِنْهُ قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْذِفْ بِهِ فَقَذَفْتُ بِهِ فَتَكَسَّرَ كَمَا تَتَكَسَّرُ ‏ ‏الْقَوَارِيرُ ‏ ‏ثُمَّ نَزَلْتُ فَانْطَلَقْتُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَسْتَبِقُ حَتَّى تَوَارَيْنَا بِالْبُيُوتِ خَشْيَةَ أَنْ ‏ ‏يَلْقَانَا أَحَدٌ مِنْ النَّاسِ ‏","","",""],[610,610,"","","‏ ‏حَدَّثَنَا ‏ ‏فَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏يَاسِينُ الْعِجْلِيُّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَهْدِيُّ ‏ ‏مِنَّا أَهْلَ الْبَيْتِ يُصْلِحُهُ اللَّهُ فِي لَيْلَةٍ ‏","","",""],[611,611,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْبَرِيدِ ‏ ‏عَنْ ‏ ‏حُسَيْنِ بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَاضِي ‏ ‏الرَّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَمِيرَ الْمُؤْمِنِينَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏اجْتَمَعْتُ أَنَا ‏ ‏وَفَاطِمَةُ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏وَالْعَبَّاسُ ‏ ‏وَزَيْدُ بْنُ حَارِثَةَ ‏ ‏عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏الْعَبَّاسُ ‏ ‏يَا رَسُولَ اللَّهِ كَبِرَ سِنِّي وَرَقَّ عَظْمِي وَكَثُرَتْ مُؤْنَتِي فَإِنْ رَأَيْتَ يَا رَسُولَ اللَّهِ أَنْ تَأْمُرَ لِي بِكَذَا وَكَذَا ‏ ‏وَسْقًا ‏ ‏مِنْ طَعَامٍ فَافْعَلْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفْعَلُ فَقَالَتْ ‏ ‏فَاطِمَةُ ‏ ‏يَا رَسُولَ اللَّهِ إِنْ رَأَيْتَ أَنْ تَأْمُرَ لِي كَمَا أَمَرْتَ لِعَمِّكَ فَافْعَلْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفْعَلُ ذَلِكَ ثُمَّ قَالَ ‏ ‏زَيْدُ بْنُ حَارِثَةَ ‏ ‏يَا رَسُولَ اللَّهِ كُنْتَ أَعْطَيْتَنِي أَرْضًا كَانَتْ مَعِيشَتِي مِنْهَا ثُمَّ قَبَضْتَهَا فَإِنْ رَأَيْتَ أَنْ تَرُدَّهَا عَلَيَّ فَقَلْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفْعَلُ فَقَالَتْ ‏ ‏فَاطِمَةُ ‏ ‏يَا رَسُولَ اللَّهِ إِنْ رَأَيْتَ أَنْ تَأْمُرَ لِي كَمَا أَمَرْت لِعَمِّكَ فَافْعَلْ فَقَالَ رَسُولُ اللَّهِ نَفْعَلُ ذَلِكَ قَالَ فَقُلْتُ أَنَا يَا رَسُولَ اللَّهِ إِنْ رَأَيْتَ أَنْ تُوَلِّيَنِي هَذَا الْحَقَّ الَّذِي جَعَلَهُ اللَّهُ لَنَا فِي كِتَابِهِ مِنْ هَذَا الْخُمُسِ فَأَقْسِمُهُ فِي حَيَاتِكَ كَيْ لَا يُنَازِعَنِيهِ أَحَدٌ بَعْدَكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفْعَلُ ذَاكَ فَوَلَّانِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَسَمْتُهُ فِي حَيَاتِهِ ‏ ‏ثُمَّ وَلَّانِيهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَسَمْتُهُ فِي حَيَاتِهِ ‏ ‏ثُمَّ وَلَّانِيهِ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَسَمْتُ فِي حَيَاتِهِ حَتَّى كَانَتْ آخِرُ سَنَةٍ مِنْ سِنِي ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَإِنَّهُ أَتَاهُ مَالٌ كَثِيرٌ ‏","","",""],[612,612,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُرَحْبِيلُ بْنُ مُدْرِكٍ الْجُعْفِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نُجَيٍّ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏لِي ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كَانَتْ لِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْزِلَةٌ لَمْ تَكُنْ لِأَحَدٍ مِنْ الْخَلَائِقِ إِنِّي كُنْتُ آتِيهِ كُلَّ ‏ ‏سَحَرٍ ‏ ‏فَأُسَلِّمُ عَلَيْهِ حَتَّى يَتَنَحْنَحَ وَإِنِّي جِئْتُ ذَاتَ لَيْلَةٍ فَسَلَّمْتُ عَلَيْهِ فَقُلْتُ السَّلَامُ عَلَيْكَ يَا نَبِيَّ اللَّهِ فَقَالَ عَلَى رِسْلِكَ يَا ‏ ‏أَبَا حَسَنٍ ‏ ‏حَتَّى أَخْرُجَ إِلَيْكَ فَلَمَّا خَرَجَ إِلَيَّ قُلْتُ يَا نَبِيَّ اللَّهِ أَغْضَبَكَ أَحَدٌ قَالَ لَا قُلْتُ فَمَا لَكَ لَا تُكَلِّمُنِي فِيمَا مَضَى حَتَّى كَلَّمْتَنِي اللَّيْلَةَ قَالَ سَمِعْتُ فِي الْحُجْرَةِ حَرَكَةً فَقُلْتُ مَنْ هَذَا فَقَالَ أَنَا ‏ ‏جِبْرِيلُ ‏ ‏قُلْتُ ادْخُلْ قَالَ لَا اخْرُجْ إِلَيَّ فَلَمَّا خَرَجْتُ قَالَ إِنَّ فِي بَيْتِكَ شَيْئًا لَا يَدْخُلُهُ مَلَكٌ مَا دَامَ فِيهِ قُلْتُ مَا أَعْلَمُهُ يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ اذْهَبْ فَانْظُرْ فَفَتَحْتُ الْبَيْتَ فَلَمْ أَجِدْ فِيهِ شَيْئًا غَيْرَ ‏ ‏جَرْوِ ‏ ‏كَلْبٍ كَانَ يَلْعَبُ بِهِ ‏ ‏الْحَسَنُ ‏ ‏قُلْتُ مَا وَجَدْتُ إِلَّا ‏ ‏جَرْوًا ‏ ‏قَالَ ‏ ‏إِنَّهَا ثَلَاثٌ لَنْ يَلِجَ مَلَكٌ مَا دَامَ فِيهَا أَبَدًا وَاحِدٌ مِنْهَا كَلْبٌ أَوْ جَنَابَةٌ أَوْ صُورَةُ رُوحٍ ‏","","",""],[613,613,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُرَحْبِيلُ بْنُ مُدْرِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نُجَيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَارَ مَعَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَكَانَ صَاحِبَ مِطْهَرَتِهِ فَلَمَّا حَاذَى ‏ ‏نِينَوَى ‏ ‏وَهُوَ مُنْطَلِقٌ إِلَى ‏ ‏صِفِّينَ ‏ ‏فَنَادَى ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اصْبِرْ ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏اصْبِرْ ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏بِشَطِّ الْفُرَاتِ قُلْتُ وَمَاذَا قَالَ قَالَ دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ وَعَيْنَاهُ تَفِيضَانِ قُلْتُ يَا نَبِيَّ اللَّهِ أَغْضَبَكَ أَحَدٌ مَا شَأْنُ عَيْنَيْكَ تَفِيضَانِ قَالَ ‏ ‏بَلْ قَامَ مِنْ عِنْدِي ‏ ‏جِبْرِيلُ ‏ ‏قَبْلُ فَحَدَّثَنِي أَنَّ ‏ ‏الْحُسَيْنَ ‏ ‏يُقْتَلُ بِشَطِّ الْفُرَاتِ قَالَ فَقَالَ هَلْ لَكَ إِلَى أَنْ أُشِمَّكَ مِنْ تُرْبَتِهِ قَالَ قُلْتُ نَعَمْ فَمَدَّ يَدَهُ فَقَبَضَ قَبْضَةً مِنْ تُرَابٍ فَأَعْطَانِيهَا فَلَمْ أَمْلِكْ عَيْنَيَّ أَنْ فَاضَتَا ‏","","",""],[614,614,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ الْفَزَارِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏الْأَزْهَرُ بْنُ رَاشِدٍ الْكَاهِلِيُّ ‏ ‏عَنْ ‏ ‏الْخَضِرِ بْنِ الْقَوَّاسِ ‏ ‏عَنْ ‏ ‏أَبِي سُخَيْلَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَلَا أُخْبِرُكُمْ بِأَفْضَلِ آيَةٍ فِي كِتَابِ اللَّهِ تَعَالَى حَدَّثَنَا بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏مَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ ‏ ‏وَيَعْفُو عَنْ كَثِيرٍ ‏} ‏وَسَأُفَسِّرُهَا لَكَ يَا ‏ ‏عَلِيُّ ‏ { ‏مَا أَصَابَكُمْ ‏} ‏مِنْ مَرَضٍ أَوْ عُقُوبَةٍ أَوْ ‏ ‏بَلَاءٍ ‏ ‏فِي الدُّنْيَا ‏ { ‏فَبِمَا كَسَبَتْ أَيْدِيكُمْ ‏} ‏وَاللَّهُ تَعَالَى أَكْرَمُ مِنْ أَنْ ‏ ‏يُثَنِّيَ ‏ ‏عَلَيْهِمْ الْعُقُوبَةَ فِي الْآخِرَةِ وَمَا ‏ ‏عَفَا ‏ ‏اللَّهُ تَعَالَى عَنْهُ فِي الدُّنْيَا فَاللَّهُ تَعَالَى أَحْلَمُ مِنْ أَنْ ‏ ‏يَعُودَ ‏ ‏بَعْدَ عَفْوِهِ ‏","","",""],[615,615,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَإِسْرَائِيلُ ‏ ‏وَأَبِي ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏قَالَ ‏ ‏سَأَلْنَا ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ تَطَوُّعِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّهَارِ فَقَالَ إِنَّكُمْ لَا تُطِيقُونَهُ قَالَ قُلْنَا أَخْبِرْنَا بِهِ نَأْخُذْ مِنْهُ مَا أَطَقْنَا قَالَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى الْفَجْرَ أَمْهَلَ حَتَّى إِذَا كَانَتْ الشَّمْسُ مِنْ هَا هُنَا ‏ ‏يَعْنِي مِنْ ‏ ‏قِبَلِ ‏ ‏الْمَشْرِقِ ‏ ‏مِقْدَارُهَا مِنْ صَلَاةِ الْعَصْرِ مِنْ هَاهُنَا مِنْ ‏ ‏قِبَلِ ‏ ‏الْمَغْرِبِ قَامَ فَصَلَّى رَكْعَتَيْنِ ثُمَّ يُمْهِلُ حَتَّى إِذَا كَانَتْ الشَّمْسُ مِنْ هَاهُنَا ‏ ‏يَعْنِي مِنْ ‏ ‏قِبَلِ ‏ ‏الْمَشْرِقِ ‏ ‏مِقْدَارُهَا مِنْ صَلَاةِ الظُّهْرِ مِنْ هَاهُنَا ‏ ‏يَعْنِي مِنْ ‏ ‏قِبَلِ ‏ ‏الْمَغْرِبِ ‏ ‏قَامَ فَصَلَّى أَرْبَعًا وَأَرْبَعًا قَبْلَ الظُّهْرِ إِذَا زَالَتْ الشَّمْسُ وَرَكْعَتَيْنِ بَعْدَهَا وَأَرْبَعًا قَبْلَ الْعَصْرِ يَفْصِلُ بَيْنَ كُلِّ رَكْعَتَيْنِ بِالتَّسْلِيمِ عَلَى الْمَلَائِكَةِ الْمُقَرَّبِينَ وَالنَّبِيِّينَ وَمَنْ تَبِعَهُمْ مِنْ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تِلْكَ سِتَّ عَشْرَةَ رَكْعَةً تَطَوُّعُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّهَارِ وَقَلَّ مَنْ يُدَاوِمُ عَلَيْهَا ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَ ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏لَأَبِي إِسْحَاقَ ‏ ‏حِينَ حَدَّثَهُ ‏ ‏يَا ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يَسْوَى حَدِيثُكَ هَذَا مِلْءَ مَسْجِدِكَ ذَهَبًا ‏","","",""],[616,616,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏وَحُسَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏مِنْ كُلِّ اللَّيْلِ قَدْ ‏ ‏أَوْتَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَوَّلِهِ وَأَوْسَطِهِ وَآخِرِهِ ‏ ‏فَثَبَتَ ‏ ‏الْوَتْرُ ‏ ‏آخِرَ اللَّيْلِ ‏","","",""],[617,617,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏الْوَتْرُ ‏ ‏لَيْسَ ‏ ‏بِحَتْمٍ ‏ ‏مِثْلَ الصَّلَاةِ وَلَكِنَّهُ ‏ ‏سُنَّةٌ ‏ ‏سَنَّهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[618,618,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَوْتَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَوَّلِ اللَّيْلِ وَآخِرِهِ وَأَوْسَطِهِ فَانْتَهَى وِتْرُهُ إِلَى ‏ ‏السَّحَرِ ‏","","",""],[619,619,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ مُضَرِّبٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُنَا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏وَنَحْنُ نَلُوذُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ أَقْرَبُنَا إِلَى الْعَدُوِّ وَكَانَ مِنْ أَشَدِّ النَّاسِ يَوْمَئِذٍ ‏ ‏بَأْسًا ‏","","",""],[620,620,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ مُسْلِمٍ الْحَنَفِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا نَكُونُ بِالْبَادِيَةِ فَتَخْرُجُ مِنْ أَحَدِنَا ‏ ‏الرُّوَيْحَةُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا ‏ ‏يَسْتَحْيِي مِنْ الْحَقِّ إِذَا فَعَلَ أَحَدُكُمْ فَلْيَتَوَضَّأْ وَلَا تَأْتُوا النِّسَاءَ فِي ‏ ‏أَعْجَازِهِنَّ ‏ ‏وَقَالَ ‏ ‏مَرَّةً فِي أَدْبَارِهِنَّ ‏","","",""],[621,621,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى الطَّبَّاعُ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عِيَاضِ بْنِ عَمْرٍو الْقَارِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏عَبْدُ اللَّهِ بْنُ شَدَّادٍ ‏ ‏فَدَخَلَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏وَنَحْنُ عِنْدَهَا جُلُوسٌ مَرْجِعَهُ مِنْ ‏ ‏الْعِرَاقِ ‏ ‏لَيَالِيَ قُتِلَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَتْ لَهُ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ شَدَّادٍ ‏ ‏هَلْ أَنْتَ صَادِقِي عَمَّا أَسْأَلُكَ عَنْهُ تُحَدِّثُنِي عَنْ هَؤُلَاءِ الْقَوْمِ الَّذِينَ قَتَلَهُمْ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ وَمَا لِي لَا أَصْدُقُكِ قَالَتْ فَحَدِّثْنِي عَنْ قِصَّتِهِمْ قَالَ فَإِنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لَمَّا ‏ ‏كَاتَبَ ‏ ‏مُعَاوِيَةَ ‏ ‏وَحَكَمَ الْحَكَمَانِ خَرَجَ عَلَيْهِ ثَمَانِيَةُ آلَافٍ مِنْ قُرَّاءِ النَّاسِ فَنَزَلُوا بِأَرْضٍ يُقَالُ لَهَا ‏ ‏حَرُورَاءُ ‏ ‏مِنْ جَانِبِ ‏ ‏الْكُوفَةِ ‏ ‏وَإِنَّهُمْ عَتَبُوا عَلَيْهِ فَقَالُوا انْسَلَخْتَ مِنْ قَمِيصٍ أَلْبَسَكَهُ اللَّهُ تَعَالَى وَاسْمٍ سَمَّاكَ اللَّهُ تَعَالَى بِهِ ثُمَّ انْطَلَقْتَ فَحَكَّمْتَ فِي دِينِ اللَّهِ فَلَا حُكْمَ إِلَّا لِلَّهِ تَعَالَى فَلَمَّا أَنْ بَلَغَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَا عَتَبُوا عَلَيْهِ وَفَارَقُوهُ عَلَيْهِ فَأَمَرَ مُؤَذِّنًا فَأَذَّنَ أَنْ لَا يَدْخُلَ عَلَى أَمِيرِ الْمُؤْمِنِينَ إِلَّا رَجُلٌ قَدْ حَمَلَ الْقُرْآنَ فَلَمَّا أَنْ امْتَلَأَتْ الدَّارُ مِنْ قُرَّاءِ النَّاسِ دَعَا بِمُصْحَفٍ إِمَامٍ عَظِيمٍ فَوَضَعَهُ بَيْنَ يَدَيْهِ فَجَعَلَ ‏ ‏يَصُكُّهُ ‏ ‏بِيَدِهِ وَيَقُولُ أَيُّهَا الْمُصْحَفُ حَدِّثْ النَّاسَ فَنَادَاهُ النَّاسُ فَقَالُوا يَا أَمِيرَ الْمُؤْمِنِينَ مَا تَسْأَلُ عَنْهُ إِنَّمَا هُوَ مِدَادٌ فِي وَرَقٍ وَنَحْنُ نَتَكَلَّمُ بِمَا رُوِينَا مِنْهُ فَمَاذَا تُرِيدُ قَالَ أَصْحَابُكُمْ هَؤُلَاءِ الَّذِينَ خَرَجُوا بَيْنِي وَبَيْنَهُمْ كِتَابُ اللَّهِ يَقُولُ اللَّهُ تَعَالَى فِي كِتَابِهِ فِي امْرَأَةٍ وَرَجُلٍ ‏ { ‏وَإِنْ خِفْتُمْ ‏ ‏شِقَاقَ ‏ ‏بَيْنِهِمَا فَابْعَثُوا حَكَمًا مِنْ أَهْلِهِ وَحَكَمًا مِنْ أَهْلِهَا إِنْ يُرِيدَا إِصْلَاحًا يُوَفِّقْ اللَّهُ بَيْنَهُمَا ‏} ‏فَأُمَّةُ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْظَمُ دَمًا وَحُرْمَةً مِنْ امْرَأَةٍ وَرَجُلٍ وَنَقَمُوا عَلَيَّ أَنْ ‏ ‏كَاتَبْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏كَتَبَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏وَقَدْ جَاءَنَا ‏ ‏سُهَيْلُ بْنُ عَمْرٍو ‏ ‏وَنَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏حِينَ صَالَحَ قَوْمَهُ ‏ ‏قُرَيْشًا ‏ ‏فَكَتَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏فَقَالَ ‏ ‏سُهَيْلٌ ‏ ‏لَا تَكْتُبْ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏فَقَالَ كَيْفَ نَكْتُبُ فَقَالَ اكْتُبْ بِاسْمِكَ اللَّهُمَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاكْتُبْ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ فَقَالَ لَوْ أَعْلَمُ أَنَّكَ رَسُولُ اللَّهِ لَمْ أُخَالِفْكَ فَكَتَبَ هَذَا مَا صَالَحَ ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏قُرَيْشًا ‏ ‏يَقُولُ اللَّهُ تَعَالَى فِي كِتَابِهِ ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِمَنْ كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ ‏} ‏فَبَعَثَ إِلَيْهِمْ ‏ ‏عَلِيٌّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَخَرَجْتُ مَعَهُ حَتَّى إِذَا تَوَسَّطْنَا عَسْكَرَهُمْ قَامَ ‏ ‏ابْنُ الْكَوَّاءِ ‏ ‏يَخْطُبُ النَّاسَ فَقَالَ يَا حَمَلَةَ الْقُرْآنِ إِنَّ هَذَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَمَنْ لَمْ يَكُنْ يَعْرِفُهُ فَأَنَا أُعَرِّفُهُ مِنْ كِتَابِ اللَّهِ مَا يَعْرِفُهُ بِهِ هَذَا مِمَّنْ نَزَلَ فِيهِ وَفِي قَوْمِهِ ‏ { ‏قَوْمٌ خَصِمُونَ ‏} ‏فَرُدُّوهُ إِلَى صَاحِبِهِ وَلَا تُوَاضِعُوهُ كِتَابَ اللَّهِ فَقَامَ خُطَبَاؤُهُمْ فَقَالُوا وَاللَّهِ لَنُوَاضِعَنَّهُ كِتَابَ اللَّهِ فَإِنْ جَاءَ بِحَقٍّ نَعْرِفُهُ لَنَتَّبِعَنَّهُ وَإِنْ جَاءَ بِبَاطِلٍ لَنُبَكِّتَنَّهُ بِبَاطِلِهِ فَوَاضَعُوا ‏ ‏عَبْدَ اللَّهِ ‏ ‏الْكِتَابَ ثَلَاثَةَ أَيَّامٍ فَرَجَعَ مِنْهُمْ أَرْبَعَةُ آلَافٍ كُلُّهُمْ تَائِبٌ فِيهِمْ ‏ ‏ابْنُ الْكَوَّاءِ ‏ ‏حَتَّى أَدْخَلَهُمْ عَلَى ‏ ‏عَلِيٍّ ‏ ‏الْكُوفَةَ ‏ ‏فَبَعَثَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِلَى بَقِيَّتِهِمْ فَقَالَ قَدْ كَانَ مِنْ أَمْرِنَا وَأَمْرِ النَّاسِ مَا قَدْ رَأَيْتُمْ فَقِفُوا حَيْثُ شِئْتُمْ حَتَّى تَجْتَمِعَ أُمَّةُ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَنَا وَبَيْنَكُمْ أَنْ لَا تَسْفِكُوا دَمًا حَرَامًا أَوْ تَقْطَعُوا ‏ ‏سَبِيلًا ‏ ‏أَوْ تَظْلِمُوا ‏ ‏ذِمَّةً ‏ ‏فَإِنَّكُمْ إِنْ فَعَلْتُمْ فَقَدْ نَبَذْنَا إِلَيْكُمْ الْحَرْبَ عَلَى سَوَاءٍ إِنَّ اللَّهَ لَا يُحِبُّ الْخَائِنِينَ فَقَالَتْ لَهُ ‏ ‏عَائِشَةُ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏يَا ‏ ‏ابْنَ شَدَّادٍ ‏ ‏فَقَدْ قَتَلَهُمْ فَقَالَ وَاللَّهِ مَا بَعَثَ إِلَيْهِمْ حَتَّى قَطَعُوا السَّبِيلَ وَسَفَكُوا الدَّمَ وَاسْتَحَلُّوا أَهْلَ الذِّمَّةِ فَقَالَتْ أَاللَّهِ قَالَ أَاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ لَقَدْ كَانَ قَالَتْ فَمَا شَيْءٌ بَلَغَنِي عَنْ أَهْلِ الذِّمَّةِ يَتَحَدَّثُونَهُ يَقُولُونَ ذُو ‏ ‏الثُّدَيِّ وَذُو ‏ ‏الثُّدَيِّ قَالَ قَدْ رَأَيْتُهُ وَقُمْتُ مَعَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَيْهِ فِي الْقَتْلَى فَدَعَا النَّاسَ فَقَالَ أَتَعْرِفُونَ هَذَا فَمَا أَكْثَرَ مَنْ جَاءَ يَقُولُ قَدْ رَأَيْتُهُ فِي مَسْجِدِ بَنِي فُلَانٍ ‏ ‏يُصَلِّي وَرَأَيْتُهُ فِي مَسْجِدِ بَنِي فُلَانٍ ‏ ‏يُصَلِّي وَلَمْ يَأْتُوا فِيهِ بِثَبَتٍ يُعْرَفُ إِلَّا ذَلِكَ قَالَتْ فَمَا قَوْلُ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حِينَ قَامَ عَلَيْهِ كَمَا يَزْعُمُ أَهْلُ ‏ ‏الْعِرَاقِ ‏ ‏قَالَ سَمِعْتُهُ يَقُولُ صَدَقَ اللَّهُ وَرَسُولُهُ قَالَتْ هَلْ سَمِعْتَ مِنْهُ أَنَّهُ قَالَ غَيْرَ ذَلِكَ قَالَ اللَّهُمَّ لَا قَالَتْ أَجَلْ صَدَقَ اللَّهُ وَرَسُولُهُ يَرْحَمُ اللَّهُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّهُ كَانَ مِنْ كَلَامِهِ لَا يَرَى شَيْئًا يُعْجِبُهُ إِلَّا قَالَ صَدَقَ اللَّهُ وَرَسُولُهُ فَيَذْهَبُ أَهْلُ ‏ ‏الْعِرَاقِ ‏ ‏يَكْذِبُونَ عَلَيْهِ وَيَزِيدُونَ عَلَيْهِ فِي الْحَدِيثِ ‏","","",""],[622,622,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنِ ‏ ‏أَبِي مُحَمَّدٍ الْهُذَلِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي جَنَازَةٍ فَقَالَ ‏ ‏أَيُّكُمْ يَنْطَلِقُ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَلَا يَدَعُ بِهَا ‏ ‏وَثَنًا ‏ ‏إِلَّا كَسَرَهُ وَلَا قَبْرًا إِلَّا سَوَّاهُ وَلَا صُورَةً إِلَّا لَطَّخَهَا فَقَالَ رَجُلٌ أَنَا يَا رَسُولَ اللَّهِ فَانْطَلَقَ ‏ ‏فَهَابَ ‏ ‏أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏فَرَجَعَ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَا أَنْطَلِقُ يَا رَسُولَ اللَّهِ قَالَ فَانْطَلِقْ فَانْطَلَقَ ثُمَّ رَجَعَ فَقَالَ يَا رَسُولَ اللَّهِ لَمْ أَدَعْ بِهَا وَثَنًا إِلَّا كَسَرْتُهُ وَلَا قَبْرًا إِلَّا سَوَّيْتُهُ وَلَا صُورَةً إِلَّا لَطَّخْتُهَا ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ عَادَ لِصَنْعَةِ شَيْءٍ مِنْ هَذَا فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ لَا تَكُونَنَّ فَتَّانًا وَلَا مُخْتَالًا وَلَا تَاجِرًا إِلَّا تَاجِرَ الْخَيْرِ فَإِنَّ أُولَئِكَ هُمْ الْمَسْبُوقُونَ بِالْعَمَلِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏قَالَ وَيُكَنُّونَهُ أَهْلُ ‏ ‏الْبَصْرَةِ ‏ ‏أَبَا مُوَرِّعٍ ‏ ‏قَالَ وَأَهْلُ ‏ ‏الْكُوفَةِ ‏ ‏يُكَنُّونَهُ ‏ ‏بِأَبِي مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي جَنَازَةٍ فَذَكَرَ الْحَدِيثَ وَلَمْ يَقُلْ عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَقَالَ وَلَا صُورَةً إِلَّا ‏ ‏طَلَخَهَا فَقَالَ مَا أَتَيْتُكَ يَا رَسُولَ اللَّهِ حَتَّى لَمْ ‏ ‏أَدَعْ ‏ ‏صُورَةً إِلَّا ‏ ‏طَلَخْتُهَا وَقَالَ لَا تَكُنْ فَتَّانًا وَلَا مُخْتَالًا ‏","","",""],[623,623,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ ‏ ‏يُوتِرُ عِنْدَ الْأَذَانِ وَيُصَلِّي الرَّكْعَتَيْنِ عِنْدَ الْإِقَامَةِ ‏","","",""],[624,624,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ يَعْنِي الرَّازِيَّ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا شَكَّ إِلَّا أَنَّهُ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آكِلَ الرِّبَا ‏ ‏وَمُوكِلَهُ وَشَاهِدَيْهِ وَكَاتِبَهُ ‏ ‏وَالْوَاشِمَةَ ‏ ‏وَالْمُسْتَوْشِمَةَ ‏ ‏وَالْمُحَلِّلَ ‏ ‏وَالْمُحَلَّلَ ‏ ‏لَهُ وَمَانِعَ ‏ ‏الصَّدَقَةِ ‏ ‏وَكَانَ يَنْهَى عَنْ ‏ ‏النَّوْحِ ‏","","",""],[625,625,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ سَوَّارٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَانَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَلِيُّ ‏ ‏إِنْ أَنْتَ وُلِّيتَ الْأَمْرَ بَعْدِي فَأَخْرِجْ أَهْلَ ‏ ‏نَجْرَانَ ‏ ‏مِنْ ‏ ‏جَزِيرَةِ الْعَرَبِ ‏","","",""],[626,626,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ يَعْنِي الرَّازِيَّ ‏ ‏وَخَالِدٌ يَعْنِي الطَّحَّانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنْتُ رَجُلًا ‏ ‏مَذَّاءً ‏ ‏فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَمَّا الْمَنِيُّ فَفِيهِ الْغُسْلُ وَأَمَّا ‏ ‏الْمَذْيُ ‏ ‏فَفِيهِ الْوُضُوءُ ‏","","",""],[627,627,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَرْفَعَ الرَّجُلُ صَوْتَهُ بِالْقِرَاءَةِ قَبْلَ الْعِشَاءِ وَبَعْدَهَا يُغَلِّطُ أَصْحَابَهُ وَهُمْ يُصَلُّونَ ‏","","",""],[628,628,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلْ اللَّهَ تَعَالَى ‏ ‏الْهُدَى ‏ ‏وَالسَّدَادَ ‏ ‏وَاذْكُرْ بِالْهُدَى هِدَايَتَكَ الطَّرِيقَ وَاذْكُرْ ‏ ‏بِالسَّدَادِ ‏ ‏تَسْدِيدَكَ ‏ ‏السَّهْمَ ‏","","",""],[629,629,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏مُحَمَّدِ بْنِ الصَّبَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ زَكَرِيَّا ‏ ‏عَنْ ‏ ‏كَثِيرٍ النَّوَّاءِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُلَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيْسَ مِنْ نَبِيٍّ كَانَ قَبْلِي إِلَّا قَدْ أُعْطِيَ سَبْعَةَ ‏ ‏نُقَبَاءَ ‏ ‏وُزَرَاءَ ‏ ‏نُجَبَاءَ ‏ ‏وَإِنِّي أُعْطِيتُ أَرْبَعَةَ عَشَرَ وَزِيرًا ‏ ‏نَقِيبًا ‏ ‏نَجِيبًا ‏ ‏سَبْعَةً مِنْ ‏ ‏قُرَيْشٍ ‏ ‏وَسَبْعَةً مِنْ ‏ ‏الْمُهَاجِرِينَ ‏","","",""],[630,630,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ مُضَرِّبٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ تَبْعَثُنِي إِلَى قَوْمٍ هُمْ ‏ ‏أَسَنُّ ‏ ‏مِنِّي لِأَقْضِيَ بَيْنَهُمْ قَالَ ‏ ‏اذْهَبْ فَإِنَّ اللَّهَ تَعَالَى سَيُثَبِّتُ لِسَانَكَ ‏ ‏وَيَهْدِي ‏ ‏قَلْبَكَ ‏","","",""],[631,631,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ غُزَيٍّ ‏ ‏حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏عِلْبَاءُ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏مَرَّتْ إِبِلُ ‏ ‏الصَّدَقَةِ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَأَهْوَى ‏ ‏بِيَدِهِ إِلَى ‏ ‏وَبَرَةٍ ‏ ‏مِنْ جَنْبِ بَعِيرٍ فَقَالَ ‏ ‏مَا أَنَا بِأَحَقَّ بِهَذِهِ ‏ ‏الْوَبَرَةِ ‏ ‏مِنْ رَجُلٍ مِنْ الْمُسْلِمِينَ ‏","","",""],[632,632,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَارِثُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زُرَيْرٍ الْغَافِقِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُصَلِّي إِذْ انْصَرَفَ وَنَحْنُ قِيَامٌ ثُمَّ أَقْبَلَ وَرَأْسُهُ يَقْطُرُ فَصَلَّى لَنَا الصَّلَاةَ ثُمَّ قَالَ ‏ ‏إِنِّي ذَكَرْتُ أَنِّي كُنْتُ ‏ ‏جُنُبًا ‏ ‏حِينَ قُمْتُ إِلَى الصَّلَاةِ لَمْ أَغْتَسِلْ فَمَنْ وَجَدَ مِنْكُمْ فِي بَطْنِهِ ‏ ‏رِزًّا ‏ ‏أَوْ كَانَ عَلَى مِثْلِ مَا كُنْتُ عَلَيْهِ فَلْيَنْصَرِفْ حَتَّى يَفْرُغَ مِنْ حَاجَتِهِ أَوْ غُسْلِهِ ثُمَّ يَعُودُ إِلَى صَلَاتِهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زُرَيْرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَذَكَرَ ‏ ‏مِثْلَهُ ‏","","",""],[633,633,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏الرَّبِيعُ يَعْنِي ابْنَ أَبِي صَالِحٍ الْأَسْلَمِيَّ ‏ ‏حَدَّثَنِي ‏ ‏زِيَادُ بْنُ أَبِي زِيَادٍ ‏ ‏سَمِعْتُ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَنْشُدُ النَّاسَ فَقَالَ ‏ ‏أَنْشُدُ اللَّهَ رَجُلًا مُسْلِمًا سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَوْمَ ‏ ‏غَدِيرِ خُمٍّ ‏ ‏مَا قَالَ فَقَامَ اثْنَا عَشَرَ بَدْرِيًّا فَشَهِدُوا ‏","","",""],[634,634,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنِ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَاحِبَ الرِّبَا وَآكِلَهُ وَكَاتِبَهُ وَشَاهِدَيْهِ ‏ ‏وَالْمُحَلِّلَ ‏ ‏وَالْمُحَلَّلَ ‏ ‏لَهُ ‏","","",""],[635,635,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُسْلِمٍ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَثِيرٍ ‏ ‏مَوْلَى ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ سَيِّدِي ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَيْثُ قُتِلَ أَهْلُ ‏ ‏النَّهْرَوَانِ ‏ ‏فَكَأَنَّ النَّاسَ وَجَدُوا فِي أَنْفُسِهِمْ مِنْ قَتْلِهِمْ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَا أَيُّهَا النَّاسُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏حَدَّثَنَا بِأَقْوَامٍ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏ثُمَّ لَا يَرْجِعُونَ فِيهِ أَبَدًا حَتَّى يَرْجِعَ السَّهْمُ عَلَى ‏ ‏فُوقِهِ ‏ ‏وَإِنَّ ‏ ‏آيَةَ ‏ ‏ذَلِكَ أَنَّ فِيهِمْ رَجُلًا أَسْوَدَ ‏ ‏مُخْدَجَ ‏ ‏الْيَدِ إِحْدَى يَدَيْهِ كَثَدْيِ الْمَرْأَةِ لَهَا حَلَمَةٌ كَحَلَمَةِ ثَدْيِ الْمَرْأَةِ حَوْلَهُ سَبْعُ ‏ ‏هُلْبَاتٍ ‏ ‏فَالْتَمِسُوهُ فَإِنِّي أُرَاهُ فِيهِمْ فَالْتَمَسُوهُ فَوَجَدُوهُ إِلَى ‏ ‏شَفِيرِ ‏ ‏النَّهَرِ تَحْتَ الْقَتْلَى فَأَخْرَجُوهُ فَكَبَّرَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ اللَّهُ أَكْبَرُ صَدَقَ اللَّهُ وَرَسُولُهُ وَإِنَّهُ لَمُتَقَلِّدٌ قَوْسًا لَهُ ‏ ‏عَرَبِيَّةً ‏ ‏فَأَخَذَهَا بِيَدِهِ فَجَعَلَ يَطْعَنُ بِهَا فِي مُخْدَجَتِهِ وَيَقُولُ صَدَقَ اللَّهُ وَرَسُولُهُ وَكَبَّرَ النَّاسُ حِينَ رَأَوْهُ وَاسْتَبْشَرُوا وَذَهَبَ عَنْهُمْ مَا كَانُوا يَجِدُونَ ‏","","",""],[636,636,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمُسْلِمِ عَلَى الْمُسْلِمِ مِنْ الْمَعْرُوفِ سِتٌّ يُسَلِّمُ عَلَيْهِ إِذَا لَقِيَهُ ‏ ‏وَيُشَمِّتُهُ ‏ ‏إِذَا عَطَسَ ‏ ‏وَيَعُودُهُ ‏ ‏إِذَا مَرِضَ وَيُجِيبُهُ إِذَا دَعَاهُ ‏ ‏وَيَشْهَدُهُ ‏ ‏إِذَا تُوُفِّيَ وَيُحِبُّ لَهُ مَا يُحِبُّ لِنَفْسِهِ وَيَنْصَحُ لَهُ بِالْغَيْبِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏فَذَكَرَ نَحْوَهُ بِإِسْنَادِهِ ‏ ‏وَمَعْنَاهُ ‏","","",""],[637,637,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏عَنِ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى ‏ ‏يُلْتَمَسَ ‏ ‏رَجُلٌ مِنْ أَصْحَابِي كَمَا تُلْتَمَسُ ‏ ‏أَوْ ‏ ‏تُبْتَغَى ‏ ‏الضَّالَّةُ ‏ ‏فَلَا يُوجَدُ ‏","","",""],[638,638,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ مُضَرِّبٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏مَنْ اسْتَطَعْتُمْ أَنْ ‏ ‏تَأْسِرُوهُ ‏ ‏مِنْ ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏فَإِنَّهُمْ خَرَجُوا كُرْهًا ‏","","",""],[639,639,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ { ‏وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ ‏} ‏قَالَ شِرْكُكُمْ مُطِرْنَا بِنَوْءِ كَذَا وَكَذَا بِنَجْمِ كَذَا وَكَذَا ‏","","",""],[640,640,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏وَأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ بِتِسْعِ سُوَرٍ مِنْ ‏ ‏الْمُفَصَّلِ ‏ ‏قَالَ ‏ ‏أَسْوَدُ ‏ ‏يَقْرَأُ فِي الرَّكْعَةِ الْأُولَى ‏ ‏أَلْهَاكُمْ التَّكَاثُرُ ‏ ‏وَإِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ ‏ ‏وَإِذَا زُلْزِلَتْ الْأَرْضُ ‏ ‏وَفِي الرَّكْعَةِ الثَّانِيَةِ ‏ ‏وَالْعَصْرِ ‏ ‏وَإِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏وَإِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ‏ ‏وَفِي الرَّكْعَةِ الثَّالِثَةِ ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَتَبَّتْ يَدَا ‏ ‏أَبِي لَهَبٍ ‏ ‏وَقُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[641,641,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ الْأَعْلَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي جَمِيلَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ أَمَةً لَهُمْ زَنَتْ فَحَمَلَتْ فَأَتَى ‏ ‏عَلِيٌّ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ لَهُ ‏ ‏دَعْهَا حَتَّى تَلِدَ ‏ ‏أَوْ تَضَعَ ‏ ‏ثُمَّ اجْلِدْهَا ‏","","",""],[642,642,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ ‏ ‏ابْنُ جُرْمُوزٍ ‏ ‏عَلَى ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ مَنْ هَذَا قَالُوا ‏ ‏ابْنُ جُرْمُوزٍ ‏ ‏يَسْتَأْذِنُ قَالَ ائْذَنُوا لَهُ لِيَدْخُلْ قَاتِلُ ‏ ‏الزُّبَيْرِ ‏ ‏النَّارَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ ‏ ‏حَوَارِيًّا ‏ ‏وَحَوَارِيَّ ‏ ‏الزُّبَيْرُ ‏","","",""],[643,643,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ ‏ ‏ابْنُ جُرْمُوزٍ ‏ ‏عَلَى ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَأَنَا عِنْدَهُ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بَشِّرْ قَاتِلَ ‏ ‏ابْنِ صَفِيَّةَ ‏ ‏بِالنَّارِ ثُمَّ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ ‏ ‏حَوَارِيًّا ‏ ‏وَحَوَارِيَّ ‏ ‏الزُّبَيْرُ ‏ ‏سَمِعْت ‏ ‏سُفْيَانَ ‏ ‏يَقُولُ ‏ ‏الْحَوَارِيُّ ‏ ‏النَّاصِرُ ‏","","",""],[644,644,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏سَمِعَ ‏ ‏عَاصِمَ بْنَ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي مِنْ الضُّحَى ‏","","",""],[645,645,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ حَيَّانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَبْعَثُكَ فِيمَا بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَنِي أَنْ أُسَوِّيَ كُلَّ قَبْرٍ وَأَطْمِسَ كُلَّ صَنَمٍ ‏","","",""],[646,646,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَخْمَ الرَّأْسِ ‏ ‏عَظِيمَ ‏ ‏الْعَيْنَيْنِ ‏ ‏هَدِبَ ‏ ‏الْأَشْفَارِ ‏ ‏مُشْرَبَ ‏ ‏الْعَيْنِ بِحُمْرَةٍ ‏ ‏كَثَّ ‏ ‏اللِّحْيَةِ ‏ ‏أَزْهَرَ ‏ ‏اللَّوْنِ إِذَا مَشَى ‏ ‏تَكَفَّأَ ‏ ‏كَأَنَّمَا يَمْشِي فِي صُعُدٍ وَإِذَا الْتَفَتَ الْتَفَتَ جَمِيعًا ‏ ‏شَثْنَ ‏ ‏الْكَفَّيْنِ وَالْقَدَمَيْنِ ‏","","",""],[647,647,"","","‏ ‏حَدَّثَنِي ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُوتِرُ بِثَلَاثٍ ‏","","",""],[648,648,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ مَا ‏ ‏أَحْدَثَ ‏ ‏قَبْلَ أَنْ يَمَسَّ مَاءً ‏ ‏وَرُبَّمَا قَالَ ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ رَجُلٍ عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[649,649,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُوسَى الصَّغِيرِ الطَّحَّانِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏خَرَجْتُ فَأَتَيْتُ ‏ ‏حَائِطًا ‏ ‏قَالَ فَقَالَ دَلْوٌ بِتَمْرَةٍ قَالَ فَدَلَّيْتُ حَتَّى مَلَأْتُ كَفِّي ثُمَّ أَتَيْتُ الْمَاءَ فَاسْتَعْذَبْتُ ‏ ‏يَعْنِي شَرِبْتُ ‏ ‏ثُمَّ أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَطْعَمْتُهُ بَعْضَهُ وَأَكَلْتُ أَنَا بَعْضَهُ ‏","","",""],[650,650,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي ‏ ‏نَذَرْتُ ‏ ‏أَنْ أَنْحَرَ نَاقَتِي وَكَيْتَ وَكَيْتَ قَالَ ‏ ‏أَمَّا نَاقَتُكَ فَانْحَرْهَا وَأَمَّا كَيْتَ وَكَيْتَ فَمِنْ الشَّيْطَانِ ‏","","",""],[651,651,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ يَعْنِي قُرَادًا ‏ ‏أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي الْهُذَيْلِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَسَأَلُوهُ عَنْ ‏ ‏الْوَتْرِ ‏ ‏قَالَ فَقَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نُوتِرَ هَذِهِ السَّاعَةَ ‏ ‏ثَوِّبْ ‏ ‏يَا ‏ ‏ابْنَ النَّبَّاحِ ‏ ‏أَوْ ‏ ‏أَذِّنْ ‏ ‏أَوْ أَقِمْ ‏","","",""],[652,652,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ لِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَقَدَّمَ إِلَيْكَ خَصْمَانِ فَلَا تَسْمَعْ كَلَامَ الْأَوَّلِ حَتَّى تَسْمَعَ كَلَامَ الْآخَرِ فَسَوْفَ ‏ ‏تَرَى كَيْفَ تَقْضِي ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَمَا زِلْتُ بَعْدَ ذَلِكَ قَاضِيًا ‏","","",""],[653,653,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَّامٍ عَبْدُ الْمَلِكِ بْنُ مُسْلِمٍ الْحَنَفِيُّ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ ظَبْيَانَ ‏ ‏عَنْ ‏ ‏حُكَيْمِ بْنِ سَعْدٍ أَبِي تِحْيَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ سَفَرًا قَالَ ‏ ‏بِكَ اللَّهُمَّ ‏ ‏أَصُولُ ‏ ‏وَبِكَ أَجُولُ وَبِكَ أَسِيرُ ‏","","",""],[654,654,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ هَاشِمٌ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى الثَّعْلَبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي جَمِيلَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَنِي أَنْ أُعْطِيَ ‏ ‏الْحَجَّامَ ‏ ‏أَجْرَهُ ‏","","",""],[655,655,"","","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى الرَّاسِبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ الْفَضْلِ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَمَرَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ آتِيَهُ بِطَبَقٍ يَكْتُبُ فِيهِ مَا لَا تَضِلُّ أُمَّتُهُ مِنْ بَعْدِهِ قَالَ فَخَشِيتُ أَنْ تَفُوتَنِي نَفْسُهُ قَالَ قُلْتُ إِنِّي أَحْفَظُ وَأَعِي قَالَ ‏ ‏أُوصِي بِالصَّلَاةِ وَالزَّكَاةِ وَمَا مَلَكَتْ أَيْمَانُكُمْ ‏","","",""],[656,656,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَذَبَ عَلَيَّ فِي حُلْمِهِ كُلِّفَ عَقْدَ شَعِيرَةٍ يَوْمَ الْقِيَامَةِ ‏","","",""],[657,657,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلُ بْنُ سُلَيْمَانَ يَعْنِي النُّمَيْرِيَّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ عَمْرٍو الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏سَيَكُونُ بَعْدِي اخْتِلَافٌ أَوْ أَمْرٌ فَإِنْ اسْتَطَعْتَ أَنْ تَكُونَ السِّلْمَ فَافْعَلْ ‏","","",""],[658,658,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ الْوَرَكَانِيُّ ‏ ‏وَإِسْمَاعِيلُ بْنُ مُوسَى السُّدِّيُّ ‏ ‏وَحَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ يَحْيَى رَحْمَوَيْهِ ‏ ‏قَالُوا أَنْبَأَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ ذِي حُدَّانَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ سَمَّى الْحَرْبَ عَلَى لِسَانِ نَبِيِّهِ خَدْعَةً ‏ ‏قَالَ ‏ ‏رَحْمَوَيْهِ ‏ ‏فِي حَدِيثِهِ عَلَى لِسَانِ نَبِيِّكُمْ ‏","","",""],[659,659,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏وَعُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ ذِي حُدَّانَ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏عَلِيًّا ‏ ‏يَقُولُ ‏ ‏الْحَرْبُ خَدْعَةٌ عَلَى لِسَانِ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[660,660,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عَبَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏سَمِعَ ‏ ‏زَيْدَ بْنَ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُهْدِيَتْ لَهُ ‏ ‏حُلَّةٌ ‏ ‏سِيَرَاءُ ‏ ‏فَأَرْسَلَ بِهَا إِلَيَّ فَرُحْتُ بِهَا فَعَرَفْتُ فِي وَجْهِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْغَضَبَ قَالَ ‏ ‏فَقَسَمْتُهَا بَيْنَ نِسَائِي ‏","","",""],[661,661,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏وَأَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏لَا أَعْلَمُهُ إِلَّا قَدْ رَفَعَهُ ‏ ‏قَالَ ‏ ‏مَنْ كَذَبَ فِي حُلْمِهِ كُلِّفَ يَوْمَ الْقِيَامَةِ عَقْدَ شَعِيرَةٍ ‏ ‏قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ أُرَاهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[662,662,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوَاصِلُ ‏ ‏إِلَى ‏ ‏السَّحَرِ ‏","","",""],[663,663,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏عَلَّمَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نَزَلَ بِي كَرْبٌ أَنْ أَقُولَ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ الْحَلِيمُ الْكَرِيمُ سُبْحَانَ اللَّهِ وَتَبَارَكَ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏","","",""],[664,664,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏ثُوَيْرُ بْنُ أَبِي فَاخِتَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏عَادَ ‏ ‏أَبُو مُوسَى الْأَشْعَرِيُّ ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏قَالَ فَدَخَلَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ ‏ ‏أَعَائِدًا ‏ ‏جِئْتَ يَا ‏ ‏أَبَا مُوسَى ‏ ‏أَمْ زَائِرًا فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ لَا بَلْ ‏ ‏عَائِدًا ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا ‏ ‏عَادَ ‏ ‏مُسْلِمٌ مُسْلِمًا إِلَّا صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ مِنْ حِينَ يُصْبِحُ إِلَى أَنْ يُمْسِيَ وَجَعَلَ اللَّهُ تَعَالَى لَهُ خَرِيفًا فِي الْجَنَّةِ ‏ ‏قَالَ ‏ ‏فَقُلْنَا يَا أَمِيرَ الْمُؤْمِنِينَ وَمَا الْخَرِيفُ قَالَ السَّاقِيَةُ الَّتِي تَسْقِي النَّخْلَ ‏","","",""],[665,665,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ حَكِيمٍ الْأَوْدِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى قَوْمٍ مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏مِنْ ‏ ‏الْخَوَارِجِ ‏ ‏فِيهِمْ رَجُلٌ يُقَالُ لَهُ ‏ ‏الْجَعْدُ بْنُ بَعْجَةَ ‏ ‏فَقَالَ لَهُ اتَّقِ اللَّهَ يَا ‏ ‏عَلِيُّ ‏ ‏فَإِنَّكَ مَيِّتٌ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بَلْ مَقْتُولٌ ضَرْبَةٌ عَلَى هَذَا تَخْضِبُ هَذِهِ ‏ ‏يَعْنِي لِحْيَتَهُ مِنْ رَأْسِهِ ‏ ‏عَهْدٌ ‏ ‏مَعْهُودٌ وَقَضَاءٌ مَقْضِيٌّ وَقَدْ خَابَ مَنْ ‏ ‏افْتَرَى ‏ ‏وَعَاتَبَهُ فِي لِبَاسِهِ فَقَالَ مَا لَكُمْ وَلِلِّبَاسِ هُوَ أَبْعَدُ مِنْ الْكِبْرِ وَأَجْدَرُ أَنْ يَقْتَدِيَ ‏ ‏بِيَ الْمُسْلِمُ ‏","","",""],[666,666,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ وَذَكَرَ ‏ ‏مُحَمَّدُ بْنُ كَعْبٍ الْقُرَظِيُّ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ اللَّهِ الْأَعْوَرِ ‏ ‏قَالَ ‏ ‏قُلْتُ لَآتِيَنَّ ‏ ‏أَمِيرَ الْمُؤْمِنِينَ ‏ ‏فَلَأَسْأَلَنَّهُ عَمَّا سَمِعْتُ الْعَشِيَّةَ قَالَ فَجِئْتُهُ بَعْدَ الْعِشَاءِ فَدَخَلْتُ عَلَيْهِ فَذَكَرَ الْحَدِيثَ قَالَ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنَّ أُمَّتَكَ مُخْتَلِفَةٌ بَعْدَكَ قَالَ فَقُلْتُ لَهُ فَأَيْنَ الْمَخْرَجُ يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ فَقَالَ كِتَابُ اللَّهِ تَعَالَى بِهِ يَقْصِمُ اللَّهُ كُلَّ جَبَّارٍ مَنْ ‏ ‏اعْتَصَمَ ‏ ‏بِهِ نَجَا وَمَنْ تَرَكَهُ هَلَكَ مَرَّتَيْنِ قَوْلٌ ‏ ‏فَصْلٌ ‏ ‏وَلَيْسَ بِالْهَزْلِ لَا تَخْتَلِقُهُ ‏ ‏الْأَلْسُنُ وَلَا ‏ ‏تَفْنَى أَعَاجِيبُهُ فِيهِ نَبَأُ مَا كَانَ قَبْلَكُمْ وَفَصْلُ مَا بَيْنَكُمْ وَخَبَرُ مَا هُوَ كَائِنٌ بَعْدَكُمْ ‏","","",""],[667,667,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏حَكِيمُ بْنُ حَكِيمِ بْنِ عَبَّادِ بْنِ حُنَيْفٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ مُسْلِمِ بْنِ عُبَيْدِ اللَّهِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَى ‏ ‏فَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏مِنْ اللَّيْلِ فَأَيْقَظَنَا لِلصَّلَاةِ قَالَ ثُمَّ رَجَعَ إِلَى بَيْتِهِ فَصَلَّى ‏ ‏هَوِيًّا ‏ ‏مِنْ اللَّيْلِ قَالَ فَلَمْ يَسْمَعْ لَنَا ‏ ‏حِسًّا ‏ ‏قَالَ فَرَجَعَ إِلَيْنَا فَأَيْقَظَنَا وَقَالَ قُومَا فَصَلِّيَا قَالَ فَجَلَسْتُ وَأَنَا ‏ ‏أَعْرُكُ ‏ ‏عَيْنِي وَأَقُولُ إِنَّا وَاللَّهِ مَا نُصَلِّي إِلَّا مَا ‏ ‏كُتِبَ ‏ ‏لَنَا إِنَّمَا أَنْفُسُنَا بِيَدِ اللَّهِ فَإِذَا شَاءَ أَنْ يَبْعَثَنَا بَعَثَنَا قَالَ فَوَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ وَيَضْرِبُ بِيَدِهِ عَلَى فَخِذِهِ مَا نُصَلِّي إِلَّا مَا ‏ ‏كُتِبَ ‏ ‏لَنَا مَا نُصَلِّي إِلَّا مَا ‏ ‏كُتِبَ ‏ ‏لَنَا ‏ { ‏وَكَانَ الْإِنْسَانُ أَكْثَرَ شَيْءٍ جَدَلًا ‏}","","",""],[668,668,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ جَمِيلٍ أَبُو يُوسُفَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ عَبْدِ الْمَلِكِ بْنِ حُمَيْدِ بْنِ أَبِي غَنِيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏قَالَ ‏ ‏لَمَّا خَرَجَتْ ‏ ‏الْخَوَارِجُ ‏ ‏بِالنَّهْرَوَانِ ‏ ‏قَامَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي أَصْحَابِهِ فَقَالَ إِنَّ هَؤُلَاءِ الْقَوْمَ قَدْ سَفَكُوا الدَّمَ الْحَرَامَ وَأَغَارُوا فِي سَرْحِ النَّاسِ وَهُمْ أَقْرَبُ الْعَدُوِّ إِلَيْكُمْ وَإِنْ تَسِيرُوا إِلَى عَدُوِّكُمْ أَنَا أَخَافُ أَنْ يَخْلُفَكُمْ هَؤُلَاءِ فِي ‏ ‏أَعْقَابِكُمْ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَخْرُجُ خَارِجَةٌ مِنْ أُمَّتِي لَيْسَ صَلَاتُكُمْ إِلَى صَلَاتِهِمْ بِشَيْءٍ وَلَا صِيَامُكُمْ إِلَى صِيَامِهِمْ بِشَيْءٍ وَلَا قِرَاءَتُكُمْ إِلَى قِرَاءَتِهِمْ بِشَيْءٍ يَقْرَءُونَ الْقُرْآنَ يَحْسِبُونَ أَنَّهُ لَهُمْ وَهُوَ عَلَيْهِمْ لَا ‏ ‏يُجَاوِزُ ‏ ‏حَنَاجِرَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الْإِسْلَامِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ الرَّمِيَّةِ ‏ ‏وَآيَةُ ‏ ‏ذَلِكَ أَنَّ فِيهِمْ رَجُلًا لَهُ عَضُدٌ وَلَيْسَ لَهَا ذِرَاعٌ عَلَيْهَا مِثْلُ حَلَمَةِ الثَّدْيِ عَلَيْهَا شَعَرَاتٌ بِيضٌ لَوْ يَعْلَمُ الْجَيْشُ الَّذِينَ ‏ ‏يُصِيبُونَهُمْ ‏ ‏مَا لَهُمْ عَلَى لِسَانِ نَبِيِّهِمْ لَاتَّكَلُوا عَلَى الْعَمَلِ فَسِيرُوا عَلَى اسْمِ اللَّهِ فَذَكَرَ الْحَدِيثَ بِطُولِهِ ‏","","",""],[669,669,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏وَاللَّهِ إِنَّا لَمَعَ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏بِالْجُحْفَةِ ‏ ‏وَمَعَهُ ‏ ‏رَهْطٌ ‏ ‏مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏فِيهِمْ ‏ ‏حَبِيبُ بْنُ مَسْلَمَةَ الْفِهْرِيُّ ‏ ‏إِذْ قَالَ ‏ ‏عُثْمَانُ ‏ ‏وَذُكِرَ لَهُ ‏ ‏التَّمَتُّعُ ‏ ‏بِالْعُمْرَةِ إِلَى الْحَجِّ ‏ ‏إِنَّ أَتَمَّ لِلْحَجِّ وَالْعُمْرَةِ أَنْ لَا يَكُونَا فِي أَشْهُرِ الْحَجِّ فَلَوْ أَخَّرْتُمْ هَذِهِ الْعُمْرَةَ حَتَّى تَزُورُوا هَذَا ‏ ‏الْبَيْتَ ‏ ‏زَوْرَتَيْنِ كَانَ أَفْضَلَ فَإِنَّ اللَّهَ تَعَالَى قَدْ ‏ ‏وَسَّعَ ‏ ‏فِي الْخَيْرِ ‏ ‏وَعَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي ‏ ‏بَطْنِ الْوَادِي ‏ ‏يَعْلِفُ بَعِيرًا لَهُ قَالَ فَبَلَغَهُ الَّذِي قَالَ ‏ ‏عُثْمَانُ ‏ ‏فَأَقْبَلَ حَتَّى وَقَفَ عَلَى ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ ‏ ‏أَعَمَدْتَ إِلَى ‏ ‏سُنَّةٍ ‏ ‏سَنَّهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرُخْصَةٍ رَخَّصَ اللَّهُ تَعَالَى بِهَا لِلْعِبَادِ فِي كِتَابِهِ تُضَيِّقُ عَلَيْهِمْ فِيهَا ‏ ‏وَتَنْهَى عَنْهَا وَقَدْ كَانَتْ لِذِي الْحَاجَةِ وَلِنَائِي الدَّارِ ثُمَّ أَهَلَّ بِحَجَّةٍ وَعُمْرَةٍ مَعًا ‏ ‏فَأَقْبَلَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى النَّاسِ ‏ ‏فَقَالَ ‏ ‏وَهَلْ نَهَيْتُ عَنْهَا إِنِّي لَمْ أَنْهَ عَنْهَا إِنَّمَا كَانَ رَأْيًا أَشَرْتُ بِهِ فَمَنْ شَاءَ أَخَذَ بِهِ وَمَنْ شَاءَ تَرَكَهُ ‏","","",""],[670,670,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏مَسْعُودِ بْنِ الْحَكَمِ الْأَنْصَارِيِّ ثُمَّ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَنَّهَا حَدَّثَتْهُ قَالَتْ ‏ ‏لَكَأَنِّي أَنْظُرُ إِلَى ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ عَلَى بَغْلَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْضَاءِ حِينَ وَقَفَ عَلَى شِعْبِ ‏ ‏الْأَنْصَارِ ‏ ‏فِي حَجَّةِ الْوَدَاعِ وَهُوَ يَقُولُ أَيُّهَا النَّاسُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّهَا لَيْسَتْ بِأَيَّامِ صِيَامٍ إِنَّمَا هِيَ أَيَّامُ أَكْلٍ وَشُرْبٍ وَذِكْرٍ ‏","","",""],[671,671,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏وَسَعْدٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏قَالَ ‏ ‏سَعْدٌ ‏ ‏ابْنِ الْهَادِ ‏ ‏سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏مَا سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْمَعُ أَبَاهُ وَأُمَّهُ لِأَحَدٍ غَيْرَ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏فَإِنِّي سَمِعْتُهُ يَقُولُ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏ارْمِ يَا ‏ ‏سَعْدُ ‏ ‏فِدَاكَ أَبِي وَأُمِّي ‏","","",""],[672,672,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏نَهَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَقُولُ نَهَاكُمْ عَنْ تَخَتُّمِ الذَّهَبِ وَعَنْ لُبْسِ ‏ ‏الْقَسِّيِّ ‏ ‏وَالْمُعَصْفَرِ ‏ ‏وَقِرَاءَةِ الْقُرْآنِ وَأَنَا رَاكِعٌ وَكَسَانِي ‏ ‏حُلَّةً ‏ ‏مِنْ ‏ ‏سِيَرَاءَ ‏ ‏فَخَرَجْتُ فِيهَا فَقَالَ يَا ‏ ‏عَلِيُّ ‏ ‏إِنِّي لَمْ أَكْسُكَهَا لِتَلْبَسَهَا قَالَ فَرَجَعْتُ بِهَا إِلَى ‏ ‏فَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَأَعْطَيْتُهَا نَاحِيَتَهَا فَأَخَذَتْ بِهَا لِتَطْوِيَهَا مَعِي فَشَقَّقْتُهَا بِثِنْتَيْنِ قَالَ فَقَالَتْ ‏ ‏تَرِبَتْ ‏ ‏يَدَاكَ يَا ‏ ‏ابْنَ أَبِي طَالِبٍ ‏ ‏مَاذَا صَنَعْتَ قَالَ فَقُلْتُ لَهَا نَهَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُبْسِهَا فَالْبَسِي وَاكْسِي نِسَاءَكِ ‏","","",""],[673,673,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏عَفَوْتُ لَكُمْ عَنْ الْخَيْلِ ‏ ‏وَالرَّقِيقِ ‏ ‏فَهَاتُوا ‏ ‏صَدَقَةَ ‏ ‏الرِّقَّةِ مِنْ كُلِّ أَرْبَعِينَ دِرْهَمًا دِرْهَمًا وَلَيْسَ فِي تِسْعِينَ وَمِائَةٍ شَيْءٌ فَإِذَا بَلَغَتْ مِائَتَيْنِ فَفِيهَا خَمْسَةُ دَرَاهِمَ ‏","","",""],[674,674,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُعَلِّمُكَ كَلِمَاتٍ إِذَا قُلْتَهُنَّ غُفِرَ لَكَ مَعَ أَنَّهُ مَغْفُورٌ لَكَ لَا إِلَهَ إِلَّا اللَّهُ الْحَلِيمُ الْكَرِيمُ لَا إِلَهَ إِلَّا اللَّهُ الْعَلِيُّ الْعَظِيمُ سُبْحَانَ اللَّهِ رَبِّ السَّمَوَاتِ السَّبْعِ وَرَبِّ الْعَرْشِ الْعَظِيمِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏","","",""],[675,675,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ ظَبْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي تِحْيَى ‏ ‏قَالَ ‏ ‏لَمَّا ضَرَبَ ‏ ‏ابْنُ مُلْجِمٍ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏الضَّرْبَةَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏افْعَلُوا بِهِ كَمَا أَرَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَفْعَلَ بِرَجُلٍ أَرَادَ قَتْلَهُ فَقَالَ اقْتُلُوهُ ثُمَّ حَرِّقُوهُ ‏","","",""],[676,676,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنِ ‏ ‏الْمِنْهَالِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ دِجَاجَةَ ‏ ‏أَنَّهُ قَالَ دَخَلَ ‏ ‏أَبُو مَسْعُودٍ عُقْبَةُ بْنُ عَمْرٍو الْأَنْصَارِيُّ ‏ ‏عَلَى ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏أَنْتَ الَّذِي تَقُولُ لَا يَأْتِي عَلَى النَّاسِ مِائَةُ سَنَةٍ وَعَلَى الْأَرْضِ عَيْنٌ ‏ ‏تَطْرِفُ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْتِي عَلَى النَّاسِ مِائَةُ سَنَةٍ وَعَلَى الْأَرْضِ عَيْنٌ ‏ ‏تَطْرِفُ ‏ ‏مِمَّنْ هُوَ حَيٌّ الْيَوْمَ وَاللَّهِ إِنَّ رَجَاءَ هَذِهِ الْأُمَّةِ بَعْدَ مِائَةِ عَامٍ ‏","","",""],[677,677,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏جَهَّزَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فِي ‏ ‏خَمِيلٍ ‏ ‏وَقِرْبَةٍ وَوِسَادَةِ ‏ ‏أَدَمٍ ‏ ‏حَشْوُهَا ‏ ‏إِذْخِرٌ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏لِيفٌ ‏","","",""],[678,678,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏وَالْمُجَالِدُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّهُمَا سَمِعَاهُ يُحَدِّثُ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حِينَ ‏ ‏رَجَمَ ‏ ‏الْمَرْأَةَ مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏ضَرَبَهَا يَوْمَ الْخَمِيسِ وَرَجَمَهَا يَوْمَ الْجُمُعَةِ وَقَالَ أَجْلِدُهَا بِكِتَابِ اللَّهِ وَأَرْجُمُهَا بِسُنَّةِ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[679,679,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْفَضْلِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ فُلَانِ بْنِ رَبِيعَةَ بْنِ الْحَارِثِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏الْهَاشِمِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏إِذَا قَامَ إِلَى الصَّلَاةِ الْمَكْتُوبَةِ كَبَّرَ وَرَفَعَ يَدَيْهِ ‏ ‏حَذْوَ ‏ ‏مَنْكِبَيْهِ ‏ ‏وَيَصْنَعُ مِثْلَ ذَلِكَ إِذَا ‏ ‏قَضَى ‏ ‏قِرَاءَتَهُ وَأَرَادَ أَنْ يَرْكَعَ وَيَصْنَعُهُ إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ وَلَا يَرْفَعُ يَدَيْهِ فِي شَيْءٍ مِنْ صَلَاتِهِ وَهُوَ قَاعِدٌ وَإِذَا قَامَ مِنْ السَّجْدَتَيْنِ رَفَعَ يَدَيْهِ كَذَلِكَ وَكَبَّرَ ‏","","",""],[680,680,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏أَنْبَأَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ دِجَاجَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏أَبُو مَسْعُودٍ ‏ ‏عَلَى ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ أَنْتَ الْقَائِلُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْتِي عَلَى النَّاسِ مِائَةُ عَامٍ وَعَلَى الْأَرْضِ نَفْسٌ ‏ ‏مَنْفُوسَةٌ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْتِي عَلَى النَّاسِ مِائَةُ عَامٍ وَعَلَى الْأَرْضِ نَفْسٌ ‏ ‏مَنْفُوسَةٌ ‏ ‏مِمَّنْ هُوَ حَيٌّ الْيَوْمَ وَإِنَّ رَجَاءَ هَذِهِ الْأُمَّةِ بَعْدَ الْمِائَةِ ‏","","",""],[681,681,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ الْخُرَاسَانِيِّ ‏ ‏أَنَّهُ حَدَّثَهُ عَنْ ‏ ‏مَوْلَى امْرَأَتِهِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ يَوْمُ الْجُمُعَةِ خَرَجَ الشَّيَاطِينُ ‏ ‏يُرَبِّثُونَ ‏ ‏النَّاسَ إِلَى أَسْوَاقِهِمْ وَمَعَهُمْ ‏ ‏الرَّايَاتُ ‏ ‏وَتَقْعُدُ الْمَلَائِكَةُ عَلَى أَبْوَابِ الْمَسَاجِدِ يَكْتُبُونَ النَّاسَ عَلَى قَدْرِ مَنَازِلِهِمْ السَّابِقَ وَالْمُصَلِّيَ وَالَّذِي يَلِيهِ حَتَّى يَخْرُجَ الْإِمَامُ فَمَنْ ‏ ‏دَنَا ‏ ‏مِنْ الْإِمَامِ فَأَنْصَتَ أَوْ اسْتَمَعَ وَلَمْ يَلْغُ كَانَ لَهُ ‏ ‏كِفْلَانِ ‏ ‏مِنْ الْأَجْرِ وَمَنْ نَأَى عَنْهُ فَاسْتَمَعَ وَأَنْصَتَ وَلَمْ يَلْغُ كَانَ لَهُ ‏ ‏كِفْلٌ ‏ ‏مِنْ الْأَجْرِ وَمَنْ ‏ ‏دَنَا ‏ ‏مِنْ الْإِمَامِ فَلَغَا وَلَمْ يُنْصِتْ وَلَمْ يَسْتَمِعْ كَانَ عَلَيْهِ ‏ ‏كِفْلَانِ ‏ ‏مِنْ الْوِزْرِ وَمَنْ نَأَى عَنْهُ فَلَغَا وَلَمْ يُنْصِتْ وَلَمْ يَسْتَمِعْ كَانَ عَلَيْهِ ‏ ‏كِفْلٌ ‏ ‏مِنْ الْوِزْرِ وَمَنْ قَالَ صَهٍ فَقَدْ تَكَلَّمَ وَمَنْ تَكَلَّمَ فَلَا جُمُعَةَ لَهُ ثُمَّ قَالَ هَكَذَا سَمِعْتُ نَبِيَّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[682,682,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى ‏ ‏يُلْتَمَسَ ‏ ‏الرَّجُلُ مِنْ أَصْحَابِي كَمَا تُلْتَمَسُ ‏ ‏الضَّالَّةُ ‏ ‏فَلَا يُوجَدُ ‏","","",""],[683,683,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَاحِبَ الرِّبَا وَآكِلَهُ وَشَاهِدَيْهِ ‏ ‏وَالْمُحَلِّلَ ‏ ‏وَالْمُحَلَّلَ ‏ ‏لَهُ ‏","","",""],[684,684,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏هُبَيْرَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ نَهَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ خَاتَمِ الذَّهَبِ ‏ ‏وَالْقَسِّيِّ ‏ ‏وَالْمِيثَرَةِ ‏","","",""],[685,685,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُودَى ‏ ‏الْمُكَاتَبُ ‏ ‏بِقَدْرِ مَا أَدَّى ‏","","",""],[686,686,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ الْإِيَامِيِّ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ جَيْشًا وَأَمَّرَ عَلَيْهِمْ رَجُلًا فَأَوْقَدَ نَارًا فَقَالَ ادْخُلُوهَا فَأَرَادَ نَاسٌ أَنْ يَدْخُلُوهَا وَقَالَ آخَرُونَ إِنَّمَا فَرَرْنَا مِنْهَا فَذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِلَّذِينَ أَرَادُوا أَنْ يَدْخُلُوهَا لَوْ دَخَلْتُمُوهَا لَمْ تَزَالُوا فِيهَا إِلَى يَوْمِ الْقِيَامَةِ وَقَالَ لِلْآخَرِينَ قَوْلًا حَسَنًا وَقَالَ ‏ ‏لَا طَاعَةَ فِي مَعْصِيَةِ اللَّهِ إِنَّمَا الطَّاعَةُ فِي الْمَعْرُوفِ ‏","","",""],[687,687,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏سَمِعْتُ ‏ ‏الْأَعْمَشَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لِلنَّاسِ مَا تَرَوْنَ فِي ‏ ‏فَضْلٍ ‏ ‏فَضَلَ ‏ ‏عِنْدَنَا مِنْ هَذَا الْمَالِ فَقَالَ النَّاسُ يَا أَمِيرَ الْمُؤْمِنِينَ قَدْ شَغَلْنَاكَ عَنْ أَهْلِكَ وَضَيْعَتِكَ وَتِجَارَتِكَ فَهُوَ لَكَ فَقَالَ لِي مَا تَقُولُ أَنْتَ فَقُلْتُ قَدْ أَشَارُوا عَلَيْكَ فَقَالَ لِي قُلْ فَقُلْتُ لِمَ تَجْعَلُ يَقِينَكَ ظَنًّا فَقَالَ لَتَخْرُجَنَّ مِمَّا قُلْتَ فَقُلْتُ أَجَلْ وَاللَّهِ لَأَخْرُجَنَّ مِنْهُ أَتَذْكُرُ حِينَ بَعَثَكَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاعِيًا ‏ ‏فَأَتَيْتَ ‏ ‏الْعَبَّاسَ بْنَ عَبْدِ الْمُطَّلِبِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَمَنَعَكَ ‏ ‏صَدَقَتَهُ ‏ ‏فَكَانَ بَيْنَكُمَا شَيْءٌ فَقُلْتَ لِي انْطَلِقْ مَعِي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدْنَاهُ ‏ ‏خَاثِرًا ‏ ‏فَرَجَعْنَا ثُمَّ ‏ ‏غَدَوْنَا ‏ ‏عَلَيْهِ فَوَجَدْنَاهُ طَيِّبَ النَّفْسِ فَأَخْبَرْتَهُ بِالَّذِي صَنَعَ فَقَالَ لَكَ ‏ ‏أَمَا عَلِمْتَ أَنَّ عَمَّ الرَّجُلِ ‏ ‏صِنْوُ ‏ ‏أَبِيهِ وَذَكَرْنَا لَهُ الَّذِي رَأَيْنَاهُ مِنْ ‏ ‏خُثُورِهِ ‏ ‏فِي الْيَوْمِ الْأَوَّلِ وَالَّذِي رَأَيْنَاهُ مِنْ طِيبِ نَفْسِهِ فِي الْيَوْمِ الثَّانِي فَقَالَ إِنَّكُمَا أَتَيْتُمَانِي فِي الْيَوْمِ الْأَوَّلِ وَقَدْ بَقِيَ عِنْدِي مِنْ ‏ ‏الصَّدَقَةِ ‏ ‏دِينَارَانِ فَكَانَ الَّذِي رَأَيْتُمَا مِنْ ‏ ‏خُثُورِي ‏ ‏لَهُ وَأَتَيْتُمَانِي الْيَوْمَ وَقَدْ وَجَّهْتُهُمَا فَذَاكَ الَّذِي رَأَيْتُمَا مِنْ طِيبِ نَفْسِي فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏صَدَقْتَ وَاللَّهِ لَأَشْكُرَنَّ لَكَ الْأُولَى وَالْآخِرَةَ ‏","","",""],[688,688,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَقَّنَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَؤُلَاءِ الْكَلِمَاتِ ‏ ‏وَأَمَرَنِي إِنْ نَزَلَ بِي كَرْبٌ أَوْ شِدَّةٌ أَنْ أَقُولَهُنَّ لَا إِلَهَ إِلَّا اللَّهُ الْكَرِيمُ الْحَلِيمُ سُبْحَانَهُ وَتَبَارَكَ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏","","",""],[689,689,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَرَكَ مَوْضِعَ شَعَرَةٍ مِنْ ‏ ‏جَنَابَةٍ ‏ ‏لَمْ يُصِبْهَا مَاءٌ فَعَلَ اللَّهُ تَعَالَى بِهِ كَذَا وَكَذَا مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَمِنْ ثَمَّ ‏ ‏عَادَيْتُ ‏ ‏شَعْرِي ‏","","",""],[690,690,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُفِّنَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَبْعَةِ أَثْوَابٍ ‏","","",""],[691,691,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ الْمَاجِشُونُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْفَضْلِ ‏ ‏وَالْمَاجِشُونُ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏عَنِ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا كَبَّرَ اسْتَفْتَحَ ثُمَّ قَالَ ‏ ‏وَجَّهْتُ وَجْهِي لِلَّذِي فَطَرَ السَّمَوَاتِ وَالْأَرْضَ حَنِيفًا مُسْلِمًا وَمَا أَنَا مِنْ الْمُشْرِكِينَ إِنَّ صَلَاتِي ‏ ‏وَنُسُكِي ‏ ‏وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنْ الْمُسْلِمِينَ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏وَأَنَا أَوَّلُ الْمُسْلِمِينَ ‏ ‏اللَّهُمَّ لَا إِلَهَ إِلَّا أَنْتَ أَنْتَ رَبِّي وَأَنَا عَبْدُكَ ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ ‏ ‏عَنِّي سَيِّئَهَا إِلَّا أَنْتَ تَبَارَكْتَ وَتَعَالَيْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ وَكَانَ إِذَا رَكَعَ قَالَ اللَّهُمَّ لَكَ رَكَعْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ خَشَعَ لَكَ سَمْعِي وَبَصَرِي وَمُخِّي وَعِظَامِي وَعَصَبِي وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرَّكْعَةِ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا وَلَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ وَإِذَا سَجَدَ قَالَ اللَّهُمَّ لَكَ سَجَدْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ فَصَوَّرَهُ فَأَحْسَنَ صُوَرَهُ فَشَقَّ سَمْعَهُ وَبَصَرَهُ فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ فَإِذَا سَلَّمَ مِنْ الصَّلَاةِ قَالَ اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ ‏","","",""],[692,692,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏فِطْرٌ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ ‏ ‏عَنِ ‏ ‏ابْنِ الْحَنَفِيَّةِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَا رَسُولَ اللَّهِ أَرَأَيْتَ ‏ ‏إِنْ وُلِدَ لِي بَعْدَكَ وَلَدٌ ‏ ‏أُسَمِّيهِ بِاسْمِكَ ‏ ‏وَأُكَنِّيهِ بِكُنْيَتِكَ قَالَ نَعَمْ فَكَانَتْ رُخْصَةً مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعَلِيٍّ ‏","","",""],[693,693,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏عَهِدَ إِلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏لَا يُحِبُّكَ إِلَّا مُؤْمِنٌ وَلَا يُبْغِضُكَ إِلَّا مُنَافِقٌ ‏","","",""],[694,694,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُجَيَّةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَسْتَشْرِفَ ‏ ‏الْعَيْنَ وَالْأُذُنَ ‏","","",""],[695,695,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْحُسَيْنِ ‏ ‏عَنْ ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏قَالَ ‏ ‏كُنَّا نَسِيرُ مَعَ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَإِذَا رَجُلٌ يُلَبِّي بِهِمَا جَمِيعًا فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَنْ هَذَا فَقَالُوا ‏ ‏عَلِيٌّ ‏ ‏فَقَالَ أَلَمْ تَعْلَمْ أَنِّي قَدْ نَهَيْتُ عَنْ هَذَا قَالَ بَلَى وَلَكِنْ لَمْ أَكُنْ لِأَدَعَ قَوْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِقَوْلِكَ ‏","","",""],[696,696,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏حُجَيَّةَ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ الْبَقَرَةِ ‏ ‏فَقَالَ عَنْ سَبْعَةٍ ‏ ‏فَقَالَ مَكْسُورَةُ الْقَرْنِ فَقَالَ لَا يَضُرُّكَ قَالَ الْعَرْجَاءُ قَالَ إِذَا ‏ ‏بَلَغَتْ ‏ ‏الْمَنْسَكَ ‏ ‏فَاذْبَحْ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَسْتَشْرِفَ ‏ ‏الْعَيْنَ وَالْأُذُنَ ‏","","",""],[697,697,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏وَأَبُو عَمْرِو بْنِ الْعَلَاءِ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏سَمِعَاهُ عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ قَوْمٌ فِيهِمْ رَجُلٌ ‏ ‏مُودَنُ ‏ ‏الْيَدِ أَوْ ‏ ‏مَثْدُونُ ‏ ‏الْيَدِ أَوْ ‏ ‏مُخْدَجُ ‏ ‏الْيَدِ وَلَوْلَا أَنْ ‏ ‏تَبْطَرُوا ‏ ‏لَأَنْبَأْتُكُمْ بِمَا وَعَدَ اللَّهُ الَّذِينَ يَقْتُلُونَهُمْ عَلَى لِسَانِ نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبِيدَةُ ‏ ‏قُلْتُ ‏ ‏لِعَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَأَنْتَ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِي وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏إِي وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏إِي وَرَبِّ ‏ ‏الْكَعْبَةِ ‏","","",""],[698,698,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى الثَّعْلَبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي جَمِيلَةَ الطُّهَوِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ خَادِمًا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْدَثَتْ ‏ ‏فَأَمَرَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أُقِيمَ عَلَيْهَا ‏ ‏الْحَدَّ ‏ ‏فَأَتَيْتُهَا فَوَجَدْتُهَا لَمْ تَجِفَّ مِنْ دَمِهَا فَأَتَيْتُهُ فَأَخْبَرْتُهُ فَقَالَ إِذَا جَفَّتْ مِنْ دَمِهَا فَأَقِمْ عَلَيْهَا ‏ ‏الْحَدَّ ‏ ‏أَقِيمُوا ‏ ‏الْحُدُودَ ‏ ‏عَلَى مَا مَلَكَتْ أَيْمَانُكُمْ ‏","","",""],[699,699,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنْتُ أَرَى أَنَّ بَاطِنَ الْقَدَمَيْنِ أَحَقُّ بِالْمَسْحِ مِنْ ‏ ‏ظَاهِرِهِمَا ‏ ‏حَتَّى رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ ‏ ‏ظَاهِرَهُمَا ‏","","",""],[700,700,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ الثَّقَفِيِّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نُنْزِيَ ‏ ‏حِمَارًا عَلَى فَرَسٍ ‏","","",""],[701,701,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ اسْتَخْلَفْتُ أَحَدًا عَنْ غَيْرِ مَشُورَةٍ لَاسْتَخْلَفْتُ ‏ ‏ابْنَ أُمِّ عَبْدٍ ‏","","",""],[702,702,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَنَّ ‏ ‏فَاطِمَةَ ‏ ‏شَكَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَثَرَ الْعَجِينِ فِي يَدَيْهَا فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْيٌ فَأَتَتْهُ تَسْأَلُهُ خَادِمًا فَلَمْ تَجِدْهُ فَرَجَعَتْ قَالَ فَأَتَانَا وَقَدْ أَخَذْنَا مَضَاجِعَنَا قَالَ فَذَهَبْتُ لِأَقُومَ فَقَالَ مَكَانَكُمَا فَجَاءَ حَتَّى جَلَسَ حَتَّى وَجَدْتُ بَرْدَ قَدَمَيْهِ فَقَالَ ‏ ‏أَلَا أَدُلُّكُمَا عَلَى مَا هُوَ خَيْرٌ لَكُمَا مِنْ خَادِمٍ إِذَا أَخَذْتُمَا مَضْجَعَكُمَا سَبَّحْتُمَا اللَّهَ ثَلَاثًا وَثَلَاثِينَ وَحَمِدْتُمَاهُ ثَلَاثًا وَثَلَاثِينَ وَكَبَّرْتُمَاهُ أَرْبَعًا وَثَلَاثِينَ ‏","","",""],[703,703,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيَّاجِ الْأَسَدِيِّ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏عَلِيٌّ ‏ ‏أَبْعَثُكَ عَلَى مَا بَعَثَنِي عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏لَا تَدَعَ تِمْثَالًا إِلَّا ‏ ‏طَمَسْتَهُ ‏ ‏وَلَا قَبْرًا ‏ ‏مُشْرِفًا ‏ ‏إِلَّا سَوَّيْتَهُ ‏","","",""],[704,704,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏ثُوَيْرِ بْنِ أَبِي فَاخِتَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ هَذِهِ السُّورَةَ ‏ ‏سَبِّحْ اسْمَ رَبِّكَ الْأَعْلَى ‏","","",""],[705,705,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏جَاءَ ثَلَاثَةُ ‏ ‏نَفَرٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَحَدُهُمْ يَا رَسُولَ اللَّهِ كَانَتْ لِي مِائَةُ دِينَارٍ فَتَصَدَّقْتُ مِنْهَا بِعَشَرَةِ دَنَانِيرَ وَقَالَ الْآخَرُ يَا رَسُولَ اللَّهِ كَانَ لِي عَشَرَةُ دَنَانِيرَ فَتَصَدَّقْتُ مِنْهَا بِدِينَارٍ وَقَالَ الْآخَرُ كَانَ لِي دِينَارٌ فَتَصَدَّقْتُ بِعُشْرِهِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّكُمْ فِي الْأَجْرِ سَوَاءٌ كُلُّكُمْ تَصَدَّقَ بِعُشْرِ مَالِهِ ‏","","",""],[706,706,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏وَمِسْعَرٌ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ هُرْمُزَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَثْنَ ‏ ‏الْكَفَّيْنِ وَالْقَدَمَيْنِ ضَخْمَ ‏ ‏الْكَرَادِيسِ ‏","","",""],[707,707,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَلَسَ إِلَيْكَ الْخَصْمَانِ فَلَا تَكَلَّمْ حَتَّى تَسْمَعَ مِنْ الْآخَرِ كَمَا سَمِعْتَ مِنْ الْأَوَّلِ ‏","","",""],[708,708,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏أَنْبَأَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ هُرْمُزَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ بِالطَّوِيلِ وَلَا بِالْقَصِيرِ ضَخْمُ الرَّأْسِ وَاللِّحْيَةِ ‏ ‏شَثْنُ ‏ ‏الْكَفَّيْنِ وَالْقَدَمَيْنِ مُشْرَبٌ وَجْهُهُ حُمْرَةً طَوِيلُ ‏ ‏الْمَسْرُبَةِ ‏ ‏ضَخْمُ ‏ ‏الْكَرَادِيسِ ‏ ‏إِذَا مَشَى ‏ ‏تَكَفَّأَ ‏ ‏تَكَفُّؤًا ‏ ‏كَأَنَّمَا يَنْحَطُّ مِنْ ‏ ‏صَبَبٍ ‏ ‏لَمْ أَرَ قَبْلَهُ وَلَا بَعْدَهُ مِثْلَهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[709,709,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏ثُوَيْرِ بْنِ أَبِي فَاخِتَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَهْدَى ‏ ‏كِسْرَى ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَبِلَ مِنْهُ وَأَهْدَى لَهُ ‏ ‏قَيْصَرُ ‏ ‏فَقَبِلَ مِنْهُ وَأَهْدَتْ لَهُ الْمُلُوكُ فَقَبِلَ مِنْهُمْ ‏","","",""],[710,710,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ هَانِئٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏عَنْ الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَتْ سَلْ ‏ ‏عَلِيًّا ‏ ‏فَإِنَّهُ أَعْلَمُ بِهَذَا مِنِّي كَانَ يُسَافِرُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَسَأَلْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمُسَافِرِ ثَلَاثَةُ أَيَّامٍ وَلَيَالِيهِنَّ وَلِلْمُقِيمِ يَوْمٌ وَلَيْلَةٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[711,711,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ أَبِي الصَّعْبَةِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زُرَيْرٍ الْغَافِقِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏أَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَهَبًا بِيَمِينِهِ وَحَرِيرًا بِشِمَالِهِ ثُمَّ رَفَعَ بِهِمَا يَدَيْهِ فَقَالَ ‏ ‏هَذَانِ حَرَامٌ عَلَى ذُكُورِ أُمَّتِي ‏","","",""],[712,712,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي آخِرِ وِتْرِهِ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ وَأَعُوذُ بِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ وَأَعُوذُ بِكَ مِنْكَ لَا أُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ ‏","","",""],[713,713,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَجْهَرَ الْقَوْمُ بَعْضُهُمْ عَلَى بَعْضٍ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ بِالْقُرْآنِ ‏","","",""],[714,714,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ رَبِيعَةَ ‏ ‏قَالَ رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أُتِيَ بِدَابَّةٍ لِيَرْكَبَهَا فَلَمَّا وَضَعَ رِجْلَهُ فِي ‏ ‏الرِّكَابِ ‏ ‏قَالَ بِسْمِ اللَّهِ فَلَمَّا ‏ ‏اسْتَوَى ‏ ‏عَلَيْهَا قَالَ ‏ ‏الْحَمْدُ لِلَّهِ سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ ‏ ‏مُقْرِنِينَ ‏ ‏وَإِنَّا إِلَى رَبِّنَا ‏ ‏لَمُنْقَلِبُونَ ‏ ‏ثُمَّ حَمِدَ اللَّهَ ثَلَاثًا وَكَبَّرَ ثَلَاثًا ثُمَّ قَالَ سُبْحَانَكَ لَا إِلَهَ إِلَّا أَنْتَ قَدْ ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي ثُمَّ ضَحِكَ فَقُلْتُ مِمَّ ضَحِكْتَ يَا أَمِيرَ الْمُؤْمِنِينَ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ مِثْلَ مَا فَعَلْتُ ثُمَّ ضَحِكَ فَقُلْتُ مِمَّ ضَحِكْتَ يَا رَسُولَ اللَّهِ قَالَ يَعْجَبُ الرَّبُّ مِنْ عَبْدِهِ إِذَا قَالَ رَبِّ اغْفِرْ لِي وَيَقُولُ عَلِمَ عَبْدِي أَنَّهُ لَا يَغْفِرُ الذُّنُوبَ غَيْرِي ‏","","",""],[715,715,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَسَارٍ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ حُرَيْثٍ ‏ ‏عَادَ ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏أَتَعُودُ ‏ ‏الْحَسَنَ ‏ ‏وَفِي نَفْسِكَ مَا فِيهَا فَقَالَ لَهُ ‏ ‏عَمْرٌو ‏ ‏إِنَّكَ لَسْتَ بِرَبِّي فَتَصْرِفَ قَلْبِي حَيْثُ شِئْتَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَمَا إِنَّ ذَلِكَ لَا يَمْنَعُنَا أَنْ نُؤَدِّيَ إِلَيْكَ النَّصِيحَةَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ مُسْلِمٍ ‏ ‏عَادَ ‏ ‏أَخَاهُ إِلَّا ابْتَعَثَ اللَّهُ لَهُ سَبْعِينَ أَلْفَ مَلَكٍ يُصَلُّونَ عَلَيْهِ مِنْ أَيِّ سَاعَاتِ النَّهَارِ كَانَ حَتَّى يُمْسِيَ وَمِنْ أَيِّ سَاعَاتِ اللَّيْلِ كَانَ حَتَّى يُصْبِحَ ‏ ‏قَالَ ‏ ‏لَهُ ‏ ‏عَمْرٌو ‏ ‏وَكَيْفَ تَقُولُ فِي الْمَشْيِ مَعَ الْجِنَازَةِ بَيْنَ يَدَيْهَا أَوْ خَلْفَهَا ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ فَضْلَ الْمَشْيِ مِنْ خَلْفِهَا عَلَى بَيْنِ يَدَيْهَا كَفَضْلِ صَلَاةِ الْمَكْتُوبَةِ فِي جَمَاعَةٍ عَلَى الْوَحْدَةِ قَالَ ‏ ‏عَمْرٌو ‏ ‏فَإِنِّي رَأَيْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏يَمْشِيَانِ أَمَامَ الْجِنَازَةِ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّهُمَا إِنَّمَا كَرِهَا أَنْ يُحْرِجَا النَّاسَ ‏","","",""],[716,716,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَسَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُلَّةً ‏ ‏سِيَرَاءَ ‏ ‏فَخَرَجْتُ فِيهَا فَرَأَيْتُ الْغَضَبَ فِي وَجْهِهِ قَالَ فَشَقَقْتُهَا بَيْنَ نِسَائِي ‏","","",""],[717,717,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ شَقِيقٍ ‏ ‏كَانَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَنْهَى عَنْ ‏ ‏الْمُتْعَةِ ‏ ‏وَعَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَأْمُرُ بِهَا فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏لِعَلِيٍّ ‏ ‏إِنَّكَ كَذَا وَكَذَا ثُمَّ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لَقَدْ عَلِمْتَ أَنَّا قَدْ ‏ ‏تَمَتَّعْنَا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَجَلْ وَلَكِنَّا كُنَّا خَائِفِينَ ‏","","",""],[718,718,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَرْبِ بْنِ أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ الدِّيْلِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي الرَّضِيعِ ‏ ‏يُنْضَحُ ‏ ‏بَوْلُ الْغُلَامِ وَيُغْسَلُ بَوْلُ ‏ ‏الْجَارِيَةِ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَهَذَا مَا لَمْ يَطْعَمَا الطَّعَامَ فَإِذَا طَعِمَا غُسِلَا جَمِيعًا ‏","","",""],[719,719,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يُؤْمِنُ عَبْدٌ حَتَّى يُؤْمِنَ بِأَرْبَعٍ حَتَّى يَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ بَعَثَنِي بِالْحَقِّ وَحَتَّى يُؤْمِنَ بِالْبَعْثِ بَعْدَ الْمَوْتِ وَحَتَّى يُؤْمِنَ بِالْقَدَرِ ‏","","",""],[720,720,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏نَاجِيَةَ بْنَ كَعْبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ ‏ ‏أَبَا طَالِبٍ ‏ ‏مَاتَ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اذْهَبْ ‏ ‏فَوَارِهِ ‏ ‏فَقَالَ إِنَّهُ مَاتَ مُشْرِكًا فَقَالَ اذْهَبْ ‏ ‏فَوَارِهِ ‏ ‏قَالَ فَلَمَّا ‏ ‏وَارَيْتُهُ ‏ ‏رَجَعْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي اغْتَسِلْ ‏","","",""],[721,721,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي عَرُوبَةَ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ عُتَيْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَبِيعَ غُلَامَيْنِ أَخَوَيْنِ فَبِعْتُهُمَا ‏ ‏وَفَرَّقْتُ ‏ ‏بَيْنَهُمَا فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَدْرِكْهُمَا فَأَرْجِعْهُمَا وَلَا تَبِعْهُمَا إِلَّا جَمِيعًا ‏","","",""],[722,722,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَيْسَ ‏ ‏الْوَتْرُ ‏ ‏بِحَتْمٍ ‏ ‏كَهَيْئَةِ الصَّلَاةِ وَلَكِنْ ‏ ‏سُنَّةٌ ‏ ‏سَنَّهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[723,723,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَشُعْبَةُ ‏ ‏وَإِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوقِظُ أَهْلَهُ فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ ‏","","",""],[724,724,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُعْطِيتُ مَا لَمْ يُعْطَ أَحَدٌ مِنْ الْأَنْبِيَاءِ فَقُلْنَا يَا رَسُولَ اللَّهِ مَا هُوَ قَالَ ‏ ‏نُصِرْتُ ‏ ‏بِالرُّعْبِ ‏ ‏وَأُعْطِيتُ مَفَاتِيحَ الْأَرْضِ وَسُمِّيتُ ‏ ‏أَحْمَدَ ‏ ‏وَجُعِلَ التُّرَابُ لِي طَهُورًا وَجُعِلَتْ أُمَّتِي خَيْرَ الْأُمَمِ ‏","","",""],[725,725,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ عِنْدَ الْأَذَانِ وَيُصَلِّي رَكْعَتَيْ الْفَجْرِ عِنْدَ الْإِقَامَةِ ‏","","",""],[726,726,"","","‏ ‏أَنْبَأَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نُجَيٍّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ذَكَرْنَا ‏ ‏الدَّجَّالَ ‏ ‏عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ نَائِمٌ ‏ ‏فَاسْتَيْقَظَ مُحْمَرًّا لَوْنُهُ فَقَالَ غَيْرُ ذَلِكَ أَخْوَفُ لِي عَلَيْكُمْ ‏ ‏ذَكَرَ كَلِمَةً ‏","","",""],[727,727,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أُهْدِيَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَغْلٌ ‏ ‏أَوْ بَغْلَةٌ ‏ ‏فَقُلْتُ مَا هَذَا قَالَ بَغْلٌ ‏ ‏أَوْ بَغْلَةٌ ‏ ‏قُلْتُ وَمِنْ أَيِّ شَيْءٍ هُوَ قَالَ ‏ ‏يُحْمَلُ الْحِمَارُ عَلَى الْفَرَسِ فَيَخْرُجُ بَيْنَهُمَا هَذَا قُلْتُ أَفَلَا نَحْمِلُ فُلَانًا عَلَى فُلَانَةَ قَالَ لَا إِنَّمَا يَفْعَلُ ذَلِكَ الَّذِينَ لَا يَعْلَمُونَ ‏","","",""],[728,728,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنْتُ إِذَا اسْتَأْذَنْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَ فِي صَلَاةٍ سَبَّحَ وَإِنْ كَانَ غَيْرَ ذَلِكَ أَذِنَ ‏","","",""],[729,729,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى ‏ ‏الْمَنْحَرَ ‏ ‏بِمِنًى ‏ ‏فَقَالَ ‏ ‏هَذَا ‏ ‏الْمَنْحَرُ ‏ ‏وَمِنًى ‏ ‏كُلُّهَا مَنْحَرٌ ‏","","",""],[730,730,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏هَانِئِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا وُلِدَ ‏ ‏الْحَسَنُ ‏ ‏سَمَّيْتُهُ ‏ ‏حَرْبًا ‏ ‏فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَرُونِي ابْنِي مَا سَمَّيْتُمُوهُ قَالَ قُلْتُ ‏ ‏حَرْبًا ‏ ‏قَالَ بَلْ هُوَ ‏ ‏حَسَنٌ ‏ ‏فَلَمَّا وُلِدَ ‏ ‏الْحُسَيْنُ ‏ ‏سَمَّيْتُهُ ‏ ‏حَرْبًا ‏ ‏فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَرُونِي ابْنِي مَا سَمَّيْتُمُوهُ قَالَ قُلْتُ ‏ ‏حَرْبًا ‏ ‏قَالَ بَلْ هُوَ ‏ ‏حُسَيْنٌ ‏ ‏فَلَمَّا وُلِدَ الثَّالِثُ سَمَّيْتُهُ ‏ ‏حَرْبًا ‏ ‏فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَرُونِي ابْنِي مَا سَمَّيْتُمُوهُ قُلْتُ ‏ ‏حَرْبًا ‏ ‏قَالَ بَلْ هُوَ ‏ ‏مُحَسِّنٌ ‏ ‏ثُمَّ قَالَ ‏ ‏سَمَّيْتُهُمْ بِأَسْمَاءِ وَلَدِ ‏ ‏هَارُونَ ‏ ‏شَبَّرُ ‏ ‏وَشَبِيرُ ‏ ‏وَمُشَبِّرٌ ‏","","",""],[731,731,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏هَانِئِ بْنِ هَانِئٍ ‏ ‏وَهُبَيْرَةَ بْنِ يَرِيمَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا خَرَجْنَا مِنْ ‏ ‏مَكَّةَ ‏ ‏اتَّبَعَتْنَا ‏ ‏ابْنَةُ حَمْزَةَ ‏ ‏تُنَادِي يَا عَمِّ وَيَا عَمِّ قَالَ فَتَنَاوَلْتُهَا بِيَدِهَا فَدَفَعْتُهَا إِلَى ‏ ‏فَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَقُلْتُ دُونَكِ ابْنَةَ عَمِّكِ قَالَ فَلَمَّا قَدِمْنَا ‏ ‏الْمَدِينَةَ ‏ ‏اخْتَصَمْنَا فِيهَا أَنَا ‏ ‏وَجَعْفَرٌ ‏ ‏وَزَيْدُ بْنُ حَارِثَةَ ‏ ‏فَقَالَ ‏ ‏جَعْفَرٌ ‏ ‏ابْنَةُ عَمِّي وَخَالَتُهَا عِنْدِي ‏ ‏يَعْنِي ‏ ‏أَسْمَاءَ بِنْتَ عُمَيْسٍ ‏ ‏وَقَالَ ‏ ‏زَيْدٌ ‏ ‏ابْنَةُ أَخِي وَقُلْتُ أَنَا أَخَذْتُهَا وَهِيَ ابْنَةُ عَمِّي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا أَنْتَ يَا ‏ ‏جَعْفَرُ ‏ ‏فَأَشْبَهْتَ خَلْقِي وَخُلُقِي وَأَمَّا أَنْتَ يَا ‏ ‏عَلِيُّ ‏ ‏فَمِنِّي وَأَنَا مِنْكَ وَأَمَّا أَنْتَ يَا ‏ ‏زَيْدُ ‏ ‏فَأَخُونَا وَمَوْلَانَا وَالْجَارِيَةُ عِنْدَ خَالَتِهَا فَإِنَّ الْخَالَةَ وَالِدَةٌ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَلَا تَزَوَّجُهَا قَالَ إِنَّهَا ابْنَةُ أَخِي مِنْ الرَّضَاعَةِ ‏","","",""],[732,732,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا يَسْتَغْفِرُ لِأَبَوَيْهِ وَهُمَا مُشْرِكَانِ فَقُلْتُ أَيَسْتَغْفِرُ الرَّجُلُ لِأَبَوَيْهِ وَهُمَا مُشْرِكَانِ فَقَالَ أَوَلَمْ يَسْتَغْفِرْ ‏ ‏إِبْرَاهِيمُ ‏ ‏لِأَبِيهِ فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَزَلَتْ ‏ { ‏مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ ‏} ‏إِلَى قَوْلِهِ ‏ { ‏تَبَرَّأَ مِنْهُ ‏} ‏قَالَ لَمَّا مَاتَ ‏ ‏فَلَا أَدْرِي قَالَهُ ‏ ‏سُفْيَانُ ‏ ‏أَوْ قَالَهُ ‏ ‏إِسْرَائِيلُ ‏ ‏أَوْ هُوَ فِي الْحَدِيثِ لَمَّا مَاتَ ‏","","",""],[733,733,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏إِيَاسُ بْنُ عَامِرٍ ‏ ‏سَمِعْتُ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَبِّحُ مِنْ اللَّيْلِ ‏ ‏وَعَائِشَةُ ‏ ‏مُعْتَرِضَةٌ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ ‏","","",""],[734,734,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فِطْرٌ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ أَبِي بَزَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ لَمْ يَبْقَ مِنْ الدُّنْيَا إِلَّا يَوْمٌ لَبَعَثَ اللَّهُ عَزَّ وَجَلَّ رَجُلًا مِنَّا يَمْلَؤُهَا عَدْلًا كَمَا مُلِئَتْ جَوْرًا ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏رَجُلًا مِنَّا ‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ ‏ ‏مَرَّةً ‏ ‏يَذْكُرُهُ عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[735,735,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏هَانِئٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏أَشْبَهُ ‏ ‏النَّاسِ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَيْنَ الصَّدْرِ إِلَى الرَّأْسِ ‏ ‏وَالْحُسَيْنُ ‏ ‏أَشْبَهُ ‏ ‏النَّاسِ بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا كَانَ أَسْفَلَ مِنْ ذَلِكَ ‏","","",""],[736,736,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏يُونُسُ بْنُ أَبِي إِسْحَاقَ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَذْنَبَ فِي الدُّنْيَا ذَنْبًا فَعُوقِبَ بِهِ فَاللَّهُ أَعْدَلُ مِنْ أَنْ ‏ ‏يُثَنِّيَ ‏ ‏عُقُوبَتَهُ عَلَى عَبْدِهِ وَمَنْ أَذْنَبَ ذَنْبًا فِي الدُّنْيَا فَسَتَرَ اللَّهُ عَلَيْهِ وَعَفَا عَنْهُ فَاللَّهُ أَكْرَمُ مِنْ أَنْ يَعُودَ فِي شَيْءٍ قَدْ عَفَا عَنْهُ ‏","","",""],[737,737,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَلَمَةَ يَعْنِي ابْنَ كُهَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏حَبَّةَ الْعُرَنِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏ضَحِكَ عَلَى الْمِنْبَرِ لَمْ أَرَهُ ضَحِكَ ضَحِكًا أَكْثَرَ مِنْهُ حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏ ‏ثُمَّ قَالَ ذَكَرْتُ قَوْلَ ‏ ‏أَبِي طَالِبٍ ‏ ‏ظَهَرَ ‏ ‏عَلَيْنَا ‏ ‏أَبُو طَالِبٍ ‏ ‏وَأَنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ نُصَلِّي ‏ ‏بِبَطْنِ نَخْلَةَ ‏ ‏فَقَالَ مَاذَا تَصْنَعَانِ يَا ابْنَ أَخِي فَدَعَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْإِسْلَامِ فَقَالَ مَا بِالَّذِي تَصْنَعَانِ ‏ ‏بَأْسٌ ‏ ‏أَوْ بِالَّذِي تَقُولَانِ ‏ ‏بَأْسٌ ‏ ‏وَلَكِنْ وَاللَّهِ لَا ‏ ‏تَعْلُوَنِي ‏ ‏اسْتِي ‏ ‏أَبَدًا وَضَحِكَ تَعَجُّبًا لِقَوْلِ أَبِيهِ ثُمَّ قَالَ اللَّهُمَّ لَا أَعْتَرِفُ أَنَّ عَبْدًا لَكَ مِنْ هَذِهِ الْأُمَّةِ عَبَدَكَ قَبْلِي غَيْرَ نَبِيِّكَ ثَلَاثَ مَرَّاتٍ لَقَدْ صَلَّيْتُ قَبْلَ أَنْ يُصَلِّيَ النَّاسُ سَبْعًا ‏","","",""],[738,738,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي ‏ ‏وَأَكْثَرُ عِلْمِي إِنْ شَاءَ اللَّهُ أَنِّي سَمِعْتُهُ مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زُرَيْرٍ الْغَافِقِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَانْصَرَفَ ثُمَّ جَاءَ وَرَأْسُهُ يَقْطُرُ مَاءً فَصَلَّى بِنَا ثُمَّ قَالَ ‏ ‏إِنِّي صَلَّيْتُ بِكُمْ ‏ ‏آنِفًا ‏ ‏وَأَنَا ‏ ‏جُنُبٌ ‏ ‏فَمَنْ أَصَابَهُ مِثْلُ الَّذِي أَصَابَنِي أَوْ وَجَدَ رِزًّا فِي بَطْنِهِ فَلْيَصْنَعْ مِثْلَ مَا صَنَعْتُ ‏","","",""],[739,739,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏كَانَ أَبِي ‏ ‏يَسْمُرُ ‏ ‏مَعَ ‏ ‏عَلِيٍّ ‏ ‏وَكَانَ ‏ ‏عَلِيٌّ ‏ ‏يَلْبَسُ ثِيَابَ الصَّيْفِ فِي الشِّتَاءِ وَثِيَابَ الشِّتَاءِ فِي الصَّيْفِ فَقِيلَ لَهُ لَوْ سَأَلْتَهُ فَسَأَلَهُ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ إِلَيَّ وَأَنَا ‏ ‏أَرْمَدُ ‏ ‏الْعَيْنِ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي ‏ ‏أَرْمَدُ ‏ ‏الْعَيْنِ قَالَ ‏ ‏فَتَفَلَ فِي عَيْنِي وَقَالَ اللَّهُمَّ أَذْهِبْ عَنْهُ الْحَرَّ وَالْبَرْدَ فَمَا وَجَدْتُ حَرًّا وَلَا بَرْدًا مُنْذُ يَوْمِئِذٍ وَقَالَ لَأُعْطِيَنَّ ‏ ‏الرَّايَةَ ‏ ‏رَجُلًا يُحِبُّ اللَّهَ وَرَسُولَهُ وَيُحِبُّهُ اللَّهُ وَرَسُولُهُ لَيْسَ بِفَرَّارٍ فَتَشَرَّفَ لَهَا ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْطَانِيهَا ‏","","",""],[740,740,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏هَانِئِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏عَمَّارٌ ‏ ‏فَاسْتَأْذَنَ فَقَالَ ‏ ‏ائْذَنُوا لَهُ مَرْحَبًا بِالطَّيِّبِ الْمُطَيَّبِ ‏","","",""],[741,741,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏وَغَيْرِهِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ هَانِئٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَتْ سَلْ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَسَأَلْتُهُ فَقَالَ ‏ ‏ثَلَاثَةُ أَيَّامٍ وَلَيَالِيهِنَّ ‏ ‏يَعْنِي لِلْمُسَافِرِ وَيَوْمٌ وَلَيْلَةٌ لِلْمُقِيمِ ‏","","",""],[742,742,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْأَشْجَعِيِّ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدَةَ بْنِ أَبِي لُبَابَةَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ هَانِئٍ ‏ ‏قَالَ ‏ ‏أَمَرَنِي ‏ ‏عَلِيٌّ ‏ ‏أَنْ أَمْسَحَ عَلَى الْخُفَّيْنِ ‏","","",""],[743,743,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُخَارِقٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ يَقُولُ عَلَى الْمِنْبَرِ ‏ ‏وَاللَّهِ مَا عِنْدَنَا كِتَابٌ نَقْرَؤُهُ عَلَيْكُمْ إِلَّا كِتَابَ اللَّهِ تَعَالَى وَهَذِهِ الصَّحِيفَةَ مُعَلَّقَةً بِسَيْفِهِ أَخَذْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا فَرَائِضُ ‏ ‏الصَّدَقَةِ ‏ ‏مُعَلَّقَةً بِسَيْفٍ لَهُ حِلْيَتُهُ حَدِيدٌ ‏ ‏أَوْ قَالَ بَكَرَاتُهُ حَدِيدٌ ‏ ‏أَيْ حِلَقُهُ ‏","","",""],[744,744,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانَ يَعْنِي ابْنَ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ بْنِ نَوْفَلٍ الْهَاشِمِيُّ ‏ ‏قَالَ ‏ ‏كَانَ أَبِي ‏ ‏الْحَارِثُ ‏ ‏عَلَى أَمْرٍ مِنْ ‏ ‏أُمُورِ ‏ ‏مَكَّةَ ‏ ‏فِي زَمَنِ ‏ ‏عُثْمَانَ ‏ ‏فَأَقْبَلَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏فَاسْتَقْبَلْتُ ‏ ‏عُثْمَانَ ‏ ‏بِالنُّزُلِ ‏ ‏بِقُدَيْدٍ ‏ ‏فَاصْطَادَ أَهْلُ الْمَاءِ حَجَلًا فَطَبَخْنَاهُ بِمَاءٍ وَمِلْحٍ فَجَعَلْنَاهُ عُرَاقًا ‏ ‏لِلثَّرِيدِ ‏ ‏فَقَدَّمْنَاهُ إِلَى ‏ ‏عُثْمَانَ ‏ ‏وَأَصْحَابِهِ فَأَمْسَكُوا فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏صَيْدٌ لَمْ أَصْطَدْهُ وَلَمْ ‏ ‏آمُرْ ‏ ‏بِصَيْدِهِ اصْطَادَهُ قَوْمٌ ‏ ‏حِلٌّ ‏ ‏فَأَطْعَمُونَاهُ فَمَا ‏ ‏بَأْسٌ ‏ ‏فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏مَنْ يَقُولُ فِي هَذَا فَقَالُوا ‏ ‏عَلِيٌّ ‏ ‏فَبَعَثَ إِلَى ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَجَاءَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏فَكَأَنِّي أَنْظُرُ إِلَى ‏ ‏عَلِيٍّ ‏ ‏حِينَ جَاءَ وَهُوَ ‏ ‏يَحُتُّ ‏ ‏الْخَبَطَ ‏ ‏عَنْ كَفَّيْهِ فَقَالَ لَهُ ‏ ‏عُثْمَانُ ‏ ‏صَيْدٌ لَمْ نَصْطَدْهُ وَلَمْ نَأْمُرْ بِصَيْدِهِ اصْطَادَهُ قَوْمٌ ‏ ‏حِلٌّ ‏ ‏فَأَطْعَمُونَاهُ فَمَا ‏ ‏بَأْسٌ ‏ ‏قَالَ فَغَضِبَ ‏ ‏عَلِيٌّ ‏ ‏وَقَالَ أَنْشُدُ اللَّهَ رَجُلًا شَهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أُتِيَ بِقَائِمَةِ حِمَارِ وَحْشٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا قَوْمٌ ‏ ‏حُرُمٌ ‏ ‏فَأَطْعِمُوهُ أَهْلَ الْحِلِّ قَالَ فَشَهِدَ اثْنَا عَشَرَ رَجُلًا مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏عَلِيٌّ ‏ ‏أُشْهِدُ اللَّهَ رَجُلًا شَهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أُتِيَ بِبَيْضِ النَّعَامِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا قَوْمٌ ‏ ‏حُرُمٌ ‏ ‏أَطْعِمُوهُ أَهْلَ الْحِلِّ قَالَ فَشَهِدَ دُونَهُمْ مِنْ ‏ ‏الْعِدَّةِ ‏ ‏مِنْ ‏ ‏الِاثْنَيْ عَشَرَ قَالَ فَثَنَى ‏ ‏عُثْمَانُ ‏ ‏وَرِكَهُ عَنْ الطَّعَامِ فَدَخَلَ ‏ ‏رَحْلَهُ ‏ ‏وَأَكَلَ ذَلِكَ الطَّعَامَ أَهْلُ الْمَاءِ ‏","","",""],[745,745,"","","‏ ‏حَدَّثَنَا ‏ ‏هُدْبَةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏أَنَّ أَبَاهُ ‏ ‏وَلِيَ ‏ ‏طَعَامَ ‏ ‏عُثْمَانَ ‏ ‏قَالَ فَكَأَنِّي أَنْظُرُ إِلَى ‏ ‏الْحَجَلِ ‏ ‏حَوَالَيْ ‏ ‏الْجِفَانِ ‏ ‏فَجَاءَ رَجُلٌ فَقَالَ إِنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَكْرَهُ هَذَا فَبَعَثَ إِلَى ‏ ‏عَلِيٍّ ‏ ‏وَهُوَ مُلَطِّخٌ يَدَيْهِ ‏ ‏بِالْخَبَطِ ‏ ‏فَقَالَ إِنَّكَ لَكَثِيرُ الْخِلَافِ عَلَيْنَا فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏أُذَكِّرُ اللَّهَ مَنْ شَهِدَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِعَجُزِ حِمَارِ وَحْشٍ وَهُوَ مُحْرِمٌ فَقَالَ ‏ ‏إِنَّا مُحْرِمُونَ فَأَطْعِمُوهُ أَهْلَ الْحِلِّ فَقَامَ رِجَالٌ فَشَهِدُوا ثُمَّ قَالَ أُذَكِّرُ اللَّهَ رَجُلًا شَهِدَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِخَمْسِ بِيضَاتٍ بَيْضِ نَعَامٍ فَقَالَ إِنَّا مُحْرِمُونَ فَأَطْعِمُوهُ أَهْلَ الْحِلِّ فَقَامَ رِجَالٌ فَشَهِدُوا فَقَامَ ‏ ‏عُثْمَانُ ‏ ‏فَدَخَلَ ‏ ‏فُسْطَاطَهُ ‏ ‏وَتَرَكُوا الطَّعَامَ عَلَى أَهْلِ الْمَاءِ ‏","","",""],[746,746,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زُرَيْرٍ الْغَافِقِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أُهْدِيَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَغْلَةٌ فَقُلْنَا يَا رَسُولَ اللَّهِ لَوْ أَنَّا أَنْزَيْنَا الْحُمُرَ عَلَى خَيْلِنَا فَجَاءَتْنَا بِمِثْلِ هَذِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا ‏ ‏يَفْعَلُ ذَلِكَ الَّذِينَ لَا يَعْلَمُونَ ‏","","",""],[747,747,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الْوَتْرَ ‏ ‏لَيْسَ ‏ ‏بِحَتْمٍ ‏ ‏وَلَكِنَّهُ ‏ ‏سُنَّةٌ ‏ ‏مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏وِتْرٌ ‏ ‏يُحِبُّ ‏ ‏الْوَتْرَ ‏","","",""],[748,748,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي إِسْحَاقُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ أَبِي الْقَاسِمِ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏مَوْلَاهُ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏اعْتَمَرْتُ مَعَ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي زَمَانِ ‏ ‏عُمَرَ ‏ ‏أَوْ زَمَانِ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَنَزَلَ عَلَى أُخْتِهِ ‏ ‏أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ ‏ ‏فَلَمَّا فَرَغَ مِنْ عُمْرَتِهِ رَجَعَ فَسُكِبَ لَهُ غُسْلٌ فَاغْتَسَلَ فَلَمَّا فَرَغَ مِنْ غُسْلِهِ دَخَلَ عَلَيْهِ نَفَرٌ مِنْ أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏فَقَالُوا يَا ‏ ‏أَبَا حَسَنٍ ‏ ‏جِئْنَاكَ نَسْأَلُكَ عَنْ أَمْرٍ نُحِبُّ أَنْ تُخْبِرَنَا عَنْهُ قَالَ أَظُنُّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏يُحَدِّثُكُمْ أَنَّهُ كَانَ أَحْدَثَ النَّاسِ عَهْدًا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا أَجَلْ عَنْ ذَلِكَ جِئْنَا نَسْأَلُكَ قَالَ ‏ ‏أَحْدَثُ النَّاسِ عَهْدًا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُثَمُ بْنُ الْعَبَّاسِ ‏","","",""],[749,749,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏عُتَيْبَةُ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ أَصْرَمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏مَاتَ رَجُلٌ مِنْ ‏ ‏أَهْلِ الصُّفَّةِ ‏ ‏وَتَرَكَ دِينَارَيْنِ ‏ ‏أَوْ دِرْهَمَيْنِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيَّتَانِ صَلُّوا عَلَى صَاحِبِكُمْ ‏","","",""],[750,750,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى الثَّعْلَبِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ كَذَبَ فِي الرُّؤْيَا مُتَعَمِّدًا كُلِّفَ عَقْدَ شَعِيرَةٍ يَوْمَ الْقِيَامَةِ ‏","","",""],[751,751,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ سُلَيْمَانَ لُوَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ رُوَيْبَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعَتْ أُذُنَايَ وَوَعَاهُ قَلْبِي عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسُ تَبَعٌ ‏ ‏لِقُرَيْشٍ ‏ ‏صَالِحُهُمْ تَبَعٌ لِصَالِحِهِمْ وَشِرَارُهُمْ تَبَعٌ لِشِرَارِهِمْ ‏","","",""],[752,752,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي سَدُوسٍ ‏ ‏يُقَالُ لَهُ ‏ ‏جُرَيُّ بْنُ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏عَضْبَاءِ ‏ ‏الْأُذُنِ وَالْقَرْنِ ‏ ‏قَالَ ‏ ‏فَسَأَلْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏فَقَالَ النِّصْفُ فَمَا فَوْقَ ذَلِكَ ‏","","",""],[753,753,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسُ بْنُ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِي الْمِقْدَامِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَزْرَقِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا نَائِمٌ عَلَى الْمَنَامَةِ فَاسْتَسْقَى ‏ ‏الْحَسَنُ ‏ ‏أَوْ ‏ ‏الْحُسَيْنُ ‏ ‏قَالَ فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى شَاةٍ لَنَا بِكْرٍ فَحَلَبَهَا فَدَرَّتْ فَجَاءَهُ ‏ ‏الْحَسَنُ ‏ ‏فَنَحَّاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏فَاطِمَةُ ‏ ‏يَا رَسُولَ اللَّهِ كَأَنَّهُ أَحَبُّهُمَا إِلَيْكَ قَالَ لَا وَلَكِنَّهُ اسْتَسْقَى قَبْلَهُ ثُمَّ قَالَ ‏ ‏إِنِّي وَإِيَّاكِ وَهَذَيْنِ وَهَذَا الرَّاقِدَ فِي مَكَانٍ وَاحِدٍ يَوْمَ الْقِيَامَةِ ‏","","",""],[754,754,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ سُلَيْمَانَ لُوَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏حُدَيْجٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجْتُ حِينَ بَزَغَ الْقَمَرُ كَأَنَّهُ ‏ ‏فِلْقُ ‏ ‏جَفْنَةٍ ‏ ‏فَقَالَ اللَّيْلَةَ لَيْلَةُ الْقَدْرِ ‏","","",""],[755,755,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏أَنَّ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَرَكَ مَوْضِعَ شَعَرَةٍ مِنْ جَسَدِهِ مِنْ ‏ ‏جَنَابَةٍ ‏ ‏لَمْ يُصِبْهَا الْمَاءُ فُعِلَ بِهِ كَذَا وَكَذَا مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَمِنْ ثَمَّ ‏ ‏عَادَيْتُ ‏ ‏رَأْسِي ‏","","",""],[756,756,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏أَنَّ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏شَرِبَ قَائِمًا فَنَظَرَ إِلَيْهِ النَّاسُ كَأَنَّهُمْ أَنْكَرُوهُ فَقَالَ ‏ ‏مَا تَنْظُرُونَ إِنْ أَشْرَبْ قَائِمًا فَقَدْ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَشْرَبُ قَائِمًا وَإِنْ أَشْرَبْ قَاعِدًا فَقَدْ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَشْرَبُ قَاعِدًا ‏","","",""],[757,757,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَخْمَ الرَّأْسِ ‏ ‏عَظِيمَ ‏ ‏الْعَيْنَيْنِ ‏ ‏هَدِبَ ‏ ‏الْأَشْفَارِ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏الشِّفَارِ ‏ ‏مُشْرَبَ الْعَيْنَيْنِ بِحُمْرَةٍ ‏ ‏كَثَّ ‏ ‏اللِّحْيَةِ ‏ ‏أَزْهَرَ ‏ ‏اللَّوْنِ ‏ ‏شَثْنَ ‏ ‏الْكَفَّيْنِ وَالْقَدَمَيْنِ إِذَا مَشَى كَأَنَّمَا يَمْشِي فِي صُعُدٍ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏تَكَفَّأَ ‏ ‏وَإِذَا الْتَفَتَ الْتَفَتَ جَمِيعًا ‏","","",""],[758,758,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ بْنُ فُضَيْلِ بْنِ عِيَاضٍ ‏ ‏وَقَالَ لِي هُوَ اسْمِي وَكُنْيَتِي ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ سُعَيْرٍ يَعْنِي ابْنَ الْخِمْسِ ‏ ‏حَدَّثَنَا ‏ ‏فُرَاتُ بْنُ أَحْنَفَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏أَنَّ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَامَ خَطِيبًا فِي ‏ ‏الرَّحَبَةِ ‏ ‏فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ مَا شَاءَ اللَّهُ أَنْ يَقُولَ ‏ ‏ثُمَّ دَعَا بِكُوزٍ مِنْ مَاءٍ فَتَمَضْمَضَ مِنْهُ وَتَمَسَّحَ وَشَرِبَ ‏ ‏فَضْلَ ‏ ‏كُوزِهِ وَهُوَ قَائِمٌ ثُمَّ قَالَ بَلَغَنِي أَنَّ الرَّجُلَ مِنْكُمْ يَكْرَهُ أَنْ يَشْرَبَ وَهُوَ قَائِمٌ وَهَذَا وُضُوءُ مَنْ لَمْ ‏ ‏يُحْدِثْ ‏ ‏وَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ هَكَذَا ‏","","",""],[759,759,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ الْوَرَكَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُخَارِقٍ ‏ ‏عَنْ ‏ ‏طَارِقٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ ‏ ‏مَا عِنْدَنَا شَيْءٌ مِنْ الْوَحْيِ ‏ ‏أَوْ قَالَ كِتَابٌ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا مَا فِي كِتَابِ اللَّهِ وَهَذِهِ الصَّحِيفَةِ الْمَقْرُونَةِ بِسَيْفِي وَعَلَيْهِ سَيْفٌ حِلْيَتُهُ حَدِيدٌ وَفِيهَا فَرَائِضُ الصَّدَقَاتِ ‏","","",""],[760,760,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَنْبَأَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏قِيلَ لَهُ إِنَّ قَاتِلَ ‏ ‏الزُّبَيْرِ ‏ ‏عَلَى الْبَابِ فَقَالَ لِيَدْخُلْ قَاتِلُ ‏ ‏ابْنِ صَفِيَّةَ ‏ ‏النَّارَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ ‏ ‏لِكُلِّ نَبِيٍّ ‏ ‏حَوَارِيًّا ‏ ‏وَإِنَّ ‏ ‏الزُّبَيْرَ ‏ ‏حَوَارِيِّي ‏","","",""],[761,761,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَإِسْحَقُ بْنُ عِيسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ أَبِي شَبِيبٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏وَهَبَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُلَامَيْنِ أَخَوَيْنِ فَبِعْتُ أَحَدَهُمَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا فَعَلَ الْغُلَامَانِ فَقُلْتُ بِعْتُ أَحَدَهُمَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُدَّهُ ‏","","",""],[762,762,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُفِّنَ فِي سَبْعَةِ أَثْوَابٍ ‏","","",""],[763,763,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ أَبِي فَضَالَةَ الْأَنْصَارِيِّ ‏ ‏وَكَانَ ‏ ‏أَبُو فَضَالَةَ ‏ ‏مِنْ أَهْلِ ‏ ‏بَدْرٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ أَبِي عَائِدًا ‏ ‏لِعَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مِنْ مَرَضٍ أَصَابَهُ ثَقُلَ مِنْهُ قَالَ فَقَالَ لَهُ أَبِي مَا يُقِيمُكَ فِي مَنْزِلِكَ هَذَا لَوْ أَصَابَكَ أَجَلُكَ لَمْ يَلِكَ إِلَّا أَعْرَابُ ‏ ‏جُهَيْنَةَ ‏ ‏تُحْمَلُ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَإِنْ أَصَابَكَ أَجَلُكَ وَلِيَكَ أَصْحَابُكَ وَصَلَّوْا عَلَيْكَ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهِدَ إِلَيَّ أَنْ لَا أَمُوتَ حَتَّى أُؤَمَّرَ ثُمَّ تُخْضَبَ هَذِهِ ‏ ‏يَعْنِي لِحْيَتَهُ ‏ ‏مِنْ دَمِ هَذِهِ ‏ ‏يَعْنِي هَامَتَهُ ‏ ‏فَقُتِلَ وَقُتِلَ ‏ ‏أَبُو فَضَالَةَ ‏ ‏مَعَ ‏ ‏عَلِيٍّ ‏ ‏يَوْمَ ‏ ‏صِفِّينَ ‏","","",""],[764,764,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏الْمَاجِشُونِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا اسْتَفْتَحَ الصَّلَاةَ يُكَبِّرُ ثُمَّ يَقُولُ ‏ ‏وَجَّهْتُ وَجْهِي لِلَّذِي فَطَرَ السَّمَوَاتِ وَالْأَرْضَ ‏ ‏حَنِيفًا ‏ ‏وَمَا أَنَا مِنْ الْمُشْرِكِينَ إِنَّ صَلَاتِي ‏ ‏وَنُسُكِي ‏ ‏وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ اللَّهُمَّ أَنْتَ الْمَلِكُ لَا إِلَهَ إِلَّا أَنْتَ أَنْتَ رَبِّي وَأَنَا عَبْدُكَ ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ اللَّهُمَّ اهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ اصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ كُلُّهُ فِي يَدَيْكَ وَالشَّرُّ لَيْسَ إِلَيْكَ أَنَا بِكَ وَإِلَيْكَ تَبَارَكْتَ وَتَعَالَيْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ وَإِذَا رَكَعَ قَالَ اللَّهُمَّ لَكَ رَكَعْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ خَشَعَ لَكَ سَمْعِي وَبَصَرِي وَمُخِّي وَعِظَامِي وَعَصَبِي وَإِذَا رَفَعَ رَأْسَهُ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا وَلَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ وَإِذَا سَجَدَ قَالَ اللَّهُمَّ لَكَ سَجَدْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ فَأَحْسَنَ صُوَرَهُ فَشَقَّ سَمْعَهُ وَبَصَرَهُ فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ وَإِذَا فَرَغَ مِنْ الصَّلَاةِ وَسَلَّمَ قَالَ اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا ‏ ‏أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏بَلَغَنَا عَنْ ‏ ‏إِسْحَاقَ بْنِ رَاهَوَيْهِ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ شُمَيْلٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏وَالشَّرُّ لَيْسَ إِلَيْكَ قَالَ لَا يُتَقَرَّبُ بِالشَّرِّ إِلَيْكَ ‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏الْمَاجِشُونِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ إِذَا افْتَتَحَ الصَّلَاةَ كَبَّرَ ثُمَّ قَالَ ‏ ‏وَجَّهْتُ وَجْهِي فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ وَاصْرِفْ عَنِّي سَيِّئَهَا ‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْفَضْلِ الْهَاشِمِيِّ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[765,765,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَزْهَرَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ لِامْرِئٍ مُسْلِمٍ أَنْ يُصْبِحَ فِي بَيْتِهِ بَعْدَ ثَلَاثٍ مِنْ لَحْمِ ‏ ‏نُسُكِهِ ‏ ‏شَيْءٌ ‏","","",""],[766,766,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ يَزِيدَ الْأَصَمُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏السُّدِّيَّ إِسْمَاعِيلَ ‏ ‏يَذْكُرُهُ عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا تُوُفِّيَ ‏ ‏أَبُو طَالِبٍ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنَّ عَمَّكَ الشَّيْخَ قَدْ مَاتَ قَالَ ‏ ‏اذْهَبْ ‏ ‏فَوَارِهِ ‏ ‏ثُمَّ لَا تُحْدِثْ شَيْئًا حَتَّى تَأْتِيَنِي قَالَ ‏ ‏فَوَارَيْتُهُ ‏ ‏ثُمَّ أَتَيْتُهُ قَالَ اذْهَبْ فَاغْتَسِلْ ثُمَّ لَا تُحْدِثْ شَيْئًا حَتَّى تَأْتِيَنِي قَالَ فَاغْتَسَلْتُ ثُمَّ أَتَيْتُهُ قَالَ فَدَعَا لِي بِدَعَوَاتٍ مَا يَسُرُّنِي أَنَّ لِي بِهَا حُمْرَ النَّعَمِ وَسُودَهَا ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِذَا غَسَّلَ الْمَيِّتَ اغْتَسَلَ ‏","","",""],[767,767,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ الْوَرَكَانِيُّ ‏ ‏فِي سَنَةِ سَبْعٍ وَعِشْرِينَ وَمِائَتَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ يَحْيَى بْنُ الْمُتَوَكِّلِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُلَيْمَانَ لُوَيْنٌ ‏ ‏فِي سَنَةِ أَرْبَعِينَ وَمِائَتَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ يَحْيَى بْنُ الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏كَثِيرٍ النَّوَّاءِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ حَسَنِ بْنِ حَسَنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَظْهَرُ فِي آخِرِ الزَّمَانِ قَوْمٌ يُسَمَّوْنَ ‏ ‏الرَّافِضَةَ ‏ ‏يَرْفُضُونَ الْإِسْلَامَ ‏","","",""],[768,768,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كُنْتُ آتِي ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْتَأْذِنُ ‏ ‏فَإِنَّ كَانَ فِي صَلَاةٍ سَبَّحَ وَإِنْ كَانَ فِي غَيْرِ صَلَاةٍ أَذِنَ لِي ‏","","",""],[769,769,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْأَعْلَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَبْدِ الرَّحْمَنِ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ مَسْلَمَةُ الرَّازِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الْبَجَلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سُفْيَانَ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ تَعَالَى يُحِبُّ الْعَبْدَ الْمُفَتَّنَ التَّوَّابَ ‏","","",""],[770,770,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ الْوَرَكَانِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو شِهَابٍ الْحَنَّاطُ عَبْدُ رَبِّهِ بْنُ نَافِعٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ بْنِ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏أَبِي يَعْلَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏أَعْيَانِي ‏ ‏أَمْرُ ‏ ‏الْمَذْيِ ‏ ‏أَمَرْتُ ‏ ‏الْمِقْدَادَ ‏ ‏أَنْ يَسْأَلَ عَنْهُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏فِيهِ الْوُضُوءُ اسْتِحْيَاءً مِنْ أَجْلِ ‏ ‏فَاطِمَةَ ‏","","",""],[771,771,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏عَنْ ‏ ‏الْمُتْعَةِ ‏ ‏وَعَنْ لُحُومِ الْحُمُرِ ‏","","",""],[772,772,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قِيلَ لَهُ إِنَّ قَاتِلَ ‏ ‏الزُّبَيْرِ ‏ ‏عَلَى الْبَابِ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏لَيَدْخُلَنَّ قَاتِلُ ‏ ‏ابْنِ صَفِيَّةَ ‏ ‏النَّارَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لِكُلِّ نَبِيٍّ ‏ ‏حَوَارِيٌّ ‏ ‏وَإِنَّ ‏ ‏حَوَارِيِّي ‏ ‏الزُّبَيْرَ بْنَ الْعَوَّامِ ‏","","",""],[773,773,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏نَزَلَ ‏ ‏قُدَيْدًا ‏ ‏فَأُتِيَ ‏ ‏بِالْحَجَلِ ‏ ‏فِي ‏ ‏الْجِفَانِ ‏ ‏شَائِلَةً بِأَرْجُلِهَا فَأَرْسَلَ إِلَى ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ ‏ ‏يَضْفِزُ ‏ ‏بَعِيرًا لَهُ فَجَاءَ ‏ ‏وَالْخَبَطُ ‏ ‏يَتَحَاتُّ ‏ ‏مِنْ يَدَيْهِ فَأَمْسَكَ ‏ ‏عَلِيٌّ ‏ ‏وَأَمْسَكَ النَّاسُ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏مَنْ هَا هُنَا مِنْ ‏ ‏أَشْجَعَ ‏ ‏هَلْ تَعْلَمُونَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَهُ أَعْرَابِيٌّ بِبَيْضَاتِ نَعَامٍ ‏ ‏وَتَتْمِيرِ ‏ ‏وَحْشٍ فَقَالَ ‏ ‏أَطْعِمْهُنَّ أَهْلَكَ فَإِنَّا حُرُمٌ قَالُوا بَلَى ‏ ‏فَتَوَرَّكَ ‏ ‏عُثْمَانُ ‏ ‏عَنْ سَرِيرِهِ وَنَزَلَ فَقَالَ ‏ ‏خَبَّثْتَ عَلَيْنَا ‏","","",""],[774,774,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَلِيُّ بْنُ مُدْرِكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ بْنَ عَمْرِو بْنِ جَرِيرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نُجَيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ كَلْبٌ وَلَا صُورَةٌ ‏","","",""],[775,775,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏سَمِعْتُ ‏ ‏هُبَيْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ نَهَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ خَاتَمِ الذَّهَبِ ‏ ‏وَالْقَسِّيِّ ‏ ‏وَالْمِيثَرَةِ ‏","","",""],[776,776,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي الطَّحَّانَ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَرْفَعَ الرَّجُلُ صَوْتَهُ بِالْقُرْآنِ قَبْلَ ‏ ‏الْعَتَمَةِ ‏ ‏وَبَعْدَهَا يُغَلِّطُ أَصْحَابَهُ فِي الصَّلَاةِ ‏","","",""],[777,777,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُودَى ‏ ‏الْمُكَاتَبُ ‏ ‏بِقَدْرِ مَا أَدَّى ‏","","",""],[778,778,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا زَوَّجَهُ ‏ ‏فَاطِمَةَ ‏ ‏بَعَثَ مَعَهَا بِخَمِيلَةٍ وَوِسَادَةٍ مِنْ أَدَمٍ حَشْوُهَا لِيفٌ وَرَحَيَيْنِ وَسِقَاءٍ وَجَرَّتَيْنِ ‏","","",""],[779,779,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏يُحَنَّسَ ‏ ‏وَصَفِيَّةَ ‏ ‏كَانَا مِنْ سَبْيِ ‏ ‏الْخُمُسِ ‏ ‏فَزَنَتْ ‏ ‏صَفِيَّةُ ‏ ‏بِرَجُلٍ مِنْ ‏ ‏الْخُمُسِ ‏ ‏فَوَلَدَتْ غُلَامًا فَادَّعَاهُ الزَّانِي ‏ ‏وَيُحَنَّسُ ‏ ‏فَاخْتَصَمَا إِلَى ‏ ‏عُثْمَانَ ‏ ‏فَرَفَعَهُمَا إِلَى ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏أَقْضِي ‏ ‏فِيهِمَا بِقَضَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ وَجَلَدَهُمَا خَمْسِينَ خَمْسِينَ ‏","","",""],[780,780,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْمُفَضَّلُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ ‏ ‏كُنَّا ‏ ‏بِمِنًى ‏ ‏فَإِذَا صَائِحٌ يَصِيحُ أَلَا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَصُومُنَّ فَإِنَّهَا أَيَّامُ أَكْلٍ وَشُرْبٍ قَالَتْ فَرَفَعْتُ أَطْنَابَ الْفُسْطَاطِ فَإِذَا الصَّائِحُ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏","","",""],[781,781,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ زَكَرِيَّا ‏ ‏عَنْ ‏ ‏حَجَّاجِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏حُجَيَّةَ بْنِ عَدِيٍّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّ ‏ ‏الْعَبَّاسَ بْنَ عَبْدِ الْمُطَّلِبِ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏تَعْجِيلِ صَدَقَتِهِ قَبْلَ أَنْ تَحِلَّ فَرَخَّصَ لَهُ ‏","","",""],[782,782,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَحْمَدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏مَخْرَمَةُ بْنُ بُكَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏أَرْسَلْتُ ‏ ‏الْمِقْدَادَ بْنَ الْأَسْوَدِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ عَنْ ‏ ‏الْمَذْيِ ‏ ‏يَخْرُجُ مِنْ الْإِنْسَانِ كَيْفَ يَفْعَلُ بِهِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأْ ‏ ‏وَانْضَحْ ‏ ‏فَرْجَكَ ‏","","",""],[783,783,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏بَيْنَمَا نَحْنُ ‏ ‏بِمِنًى ‏ ‏إِذَا ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى جَمَلٍ وَهُوَ يَقُولُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ هَذِهِ أَيَّامُ ‏ ‏طُعْمٍ ‏ ‏وَشُرْبٍ فَلَا يَصُومَنَّ أَحَدٌ فَاتَّبَعَ النَّاسُ ‏","","",""],[784,784,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَنْبَأَنِي ‏ ‏غَيْرَ مَرَّةٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَاصِمَ بْنَ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ قَالَ ‏ ‏مِنْ كُلِّ اللَّيْلِ قَدْ ‏ ‏أَوْتَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَوَّلِهِ ‏ ‏وَأَوْسَطِهِ وَآخِرِهِ وَانْتَهَى وِتْرُهُ إِلَى آخِرِ اللَّيْلِ ‏","","",""],[785,785,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سَلَمَةُ بْنُ كُهَيْلٍ ‏ ‏أَنْبَأَنِي قَالَ سَمِعْتُ ‏ ‏حُجَيَّةَ بْنَ عَدِيٍّ ‏ ‏رَجُلًا مِنْ ‏ ‏كِنْدَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا سَأَلَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ إِنِّي اشْتَرَيْتُ هَذِهِ الْبَقَرَةَ لِلْأَضْحَى قَالَ عَنْ سَبْعَةٍ قَالَ الْقَرْنُ قَالَ لَا يَضُرُّكَ قَالَ الْعَرَجُ قَالَ إِذَا بَلَغَتْ ‏ ‏الْمَنْسَكَ ‏ ‏فَانْحَرْ ثُمَّ قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَسْتَشْرِفَ ‏ ‏الْعَيْنَ وَالْأُذُنَ ‏","","",""],[786,786,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعْدُ بْنُ عُبَيْدَةَ ‏ ‏قَالَ ‏ ‏تَنَازَعَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ السُّلَمِيُّ ‏ ‏وَحِبَّانُ بْنُ عَطِيَّةَ ‏ ‏فَقَالَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏لِحِبَّانَ ‏ ‏قَدْ عَلِمْتُ مَا الَّذِي جَرَّأَ صَاحِبَكَ ‏ ‏يَعْنِي ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ فَمَا هُوَ لَا أَبَا لَكَ قَالَ ‏ ‏قَوْلٌ سَمِعْتُهُ مِنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُهُ ‏ ‏قَالَ بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالزُّبَيْرَ ‏ ‏وَأَبَا مَرْثَدٍ ‏ ‏وَكُلُّنَا فَارِسٌ قَالَ انْطَلِقُوا حَتَّى تَبْلُغُوا ‏ ‏رَوْضَةَ خَاخٍ ‏ ‏فَإِنَّ فِيهَا ‏ ‏امْرَأَةً ‏ ‏مَعَهَا صَحِيفَةٌ مِنْ ‏ ‏حَاطِبِ بْنِ أَبِي بَلْتَعَةَ ‏ ‏إِلَى الْمُشْرِكِينَ فَأْتُونِي بِهَا فَانْطَلَقْنَا عَلَى أَفْرَاسِنَا حَتَّى أَدْرَكْنَاهَا حَيْثُ قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسِيرُ عَلَى بَعِيرٍ لَهَا قَالَ وَكَانَ كَتَبَ إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏بِمَسِيرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْنَا لَهَا أَيْنَ الْكِتَابُ الَّذِي مَعَكِ قَالَتْ مَا مَعِي كِتَابٌ فَأَنَخْنَا بِهَا بَعِيرَهَا فَابْتَغَيْنَا فِي رَحْلِهَا فَلَمْ نَجِدْ فِيهِ شَيْئًا فَقَالَ صَاحِبَايَ مَا نَرَى مَعَهَا كِتَابًا فَقُلْتُ لَقَدْ عَلِمْتُمَا مَا كَذَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ حَلَفْتُ وَالَّذِي أَحْلِفُ بِهِ لَئِنْ لَمْ تُخْرِجِي الْكِتَابَ لَأُجَرِّدَنَّكِ فَأَهْوَتْ إِلَى حُجْزَتِهَا وَهِيَ مُحْتَجِزَةٌ بِكِسَاءٍ فَأَخْرَجَتْ الصَّحِيفَةَ فَأَتَوْا بِهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ قَدْ خَانَ اللَّهَ وَرَسُولَهُ وَالْمُؤْمِنِينَ دَعْنِي أَضْرِبْ عُنُقَهُ قَالَ يَا ‏ ‏حَاطِبُ ‏ ‏مَا حَمَلَكَ عَلَى مَا صَنَعْتَ قَالَ يَا رَسُولَ اللَّهِ وَاللَّهِ مَا بِي أَنْ لَا أَكُونَ مُؤْمِنًا بِاللَّهِ وَرَسُولِهِ وَلَكِنِّي أَرَدْتُ أَنْ تَكُونَ لِي عِنْدَ الْقَوْمِ يَدٌ يَدْفَعُ اللَّهُ بِهَا عَنْ أَهْلِي وَمَالِي وَلَمْ يَكُنْ أَحَدٌ مِنْ أَصْحَابِكَ إِلَّا لَهُ هُنَاكَ مِنْ قَوْمِهِ مَنْ يَدْفَعُ اللَّهُ تَعَالَى بِهِ عَنْ أَهْلِهِ وَمَالِهِ قَالَ صَدَقْتَ فَلَا تَقُولُوا لَهُ إِلَّا خَيْرًا فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّهُ قَدْ خَانَ اللَّهَ وَرَسُولَهُ وَالْمُؤْمِنِينَ دَعْنِي أَضْرِبْ عُنُقَهُ قَالَ أَوَلَيْسَ مِنْ أَهْلِ ‏ ‏بَدْرٍ ‏ ‏وَمَا يُدْرِيكَ لَعَلَّ اللَّهَ عَزَّ وَجَلَّ اطَّلَعَ عَلَيْهِمْ فَقَالَ ‏ ‏اعْمَلُوا مَا شِئْتُمْ فَقَدْ وَجَبَتْ لَكُمْ الْجَنَّةُ فَاغْرَوْرَقَتْ عَيْنَا ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَقَالَ اللَّهُ تَعَالَى وَرَسُولُهُ أَعْلَمُ ‏","","",""],[787,787,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ عَبْدِ اللَّهِ الْجُهَنِيُّ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عُمَرَ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثَةٌ يَا ‏ ‏عَلِيُّ ‏ ‏لَا تُؤَخِّرْهُنَّ الصَّلَاةُ إِذَا أَتَتْ وَالْجَنَازَةُ إِذَا حَضَرَتْ ‏ ‏وَالْأَيِّمُ ‏ ‏إِذَا وَجَدَتْ ‏ ‏كُفُؤًا ‏","","",""],[788,788,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الْمُبَارَكِيُّ سُلَيْمَانُ بْنُ مُحَمَّدٍ ‏ ‏جَارُ ‏ ‏خَلَفٍ الْبَزَّارِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ خَاتَمِ الذَّهَبِ وَعَنْ لُبْسِ الْحُمْرَةِ وَعَنْ الْقِرَاءَةِ فِي الرُّكُوعِ وَالسُّجُودِ ‏","","",""],[789,789,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ مُحَمَّدِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلَحْمِ صَيْدٍ وَهُوَ ‏ ‏مُحْرِمٌ ‏ ‏فَلَمْ يَأْكُلْهُ ‏","","",""],[790,790,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عُبَيْدِ بْنِ مُحَمَّدٍ الْمُحَارِبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْأَجْلَحِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لِبَاسِ ‏ ‏الْقَسِّيِّ ‏ ‏وَالْمَيَاثِرِ ‏ ‏وَالْمُعَصْفَرِ ‏ ‏وَعَنْ قِرَاءَةِ الْقُرْآنِ وَالرَّجُلُ رَاكِعٌ أَوْ سَاجِدٌ ‏","","",""],[791,791,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مُحَمَّدٍ سَعِيدُ بْنُ مُحَمَّدٍ الْجَرْمِيُّ ‏ ‏قَدِمَ عَلَيْنَا مِنْ ‏ ‏الْكُوفَةِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏ح ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ يَحْيَى بْنِ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏تَمَارَيْنَا ‏ ‏فِي سُورَةٍ مِنْ الْقُرْآنِ فَقُلْنَا خَمْسٌ وَثَلَاثُونَ آيَةً سِتٌّ وَثَلَاثُونَ آيَةً قَالَ فَانْطَلَقْنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدْنَا ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُنَاجِيهِ ‏ ‏فَقُلْنَا إِنَّا اخْتَلَفْنَا فِي الْقِرَاءَةِ فَاحْمَرَّ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُكُمْ أَنْ تَقْرَءُوا كَمَا عُلِّمْتُمْ ‏","","",""],[792,792,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ عَبْدِ اللَّهِ التِّرْمِذِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏ح ‏ ‏وَحَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏الْقَوَارِيرِيُّ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏زِرٍّ يَعْنِي ابْنَ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏أَبِي جُحَيْفَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ هَذِهِ الْأُمَّةِ بَعْدَ نَبِيِّهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏ثُمَّ قَالَ أَلَا أُخْبِرُكُمْ بِخَيْرِ هَذِهِ الْأُمَّةِ بَعْدَ ‏ ‏أَبِي بَكْرٍ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[793,793,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو صَالِحٍ هَدِيَّةُ بْنُ عَبْدِ الْوَهَّابِ ‏ ‏بِمَكَّةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ الطَّنَافِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ الْبَجَلِيُّ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏وَهْبٍ السُّوَائِيِّ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ مَنْ خَيْرُ هَذِهِ الْأُمَّةِ بَعْدَ نَبِيِّهَا فَقُلْتُ أَنْتَ يَا أَمِيرَ الْمُؤْمِنِينَ قَالَ لَا ‏ ‏خَيْرُ هَذِهِ الْأُمَّةِ بَعْدَ نَبِيِّهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏ثُمَّ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَمَا نُبْعِدُ أَنَّ ‏ ‏السَّكِينَةَ ‏ ‏تَنْطِقُ عَلَى لِسَانِ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[794,794,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَنْبَأَنَا ‏ ‏مَنْصُورُ بْنُ عَبْدِ الرَّحْمَنِ يَعْنِي الْغُدَانِيَّ الْأَشَلَّ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو جُحَيْفَةَ ‏ ‏الَّذِي كَانَ ‏ ‏عَلِيٌّ ‏ ‏يُسَمِّيهِ ‏ ‏وَهْبَ الْخَيْرِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَا ‏ ‏أَبَا جُحَيْفَةَ ‏ ‏أَلَا أُخْبِرُكَ بِأَفْضَلِ هَذِهِ الْأُمَّةِ بَعْدَ نَبِيِّهَا قَالَ قُلْتُ بَلَى قَالَ وَلَمْ أَكُنْ أَرَى أَنَّ أَحَدًا أَفْضَلُ مِنْهُ قَالَ ‏ ‏أَفْضَلُ هَذِهِ الْأُمَّةِ بَعْدَ نَبِيِّهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَبَعْدَ ‏ ‏أَبِي بَكْرٍ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَبَعْدَهُمَا آخَرُ ثَالِثٌ وَلَمْ يُسَمِّهِ ‏","","",""],[795,795,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي جُحَيْفَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏خَيْرُ هَذِهِ الْأُمَّةِ بَعْدَ نَبِيِّهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَبَعْدَ ‏ ‏أَبِي بَكْرٍ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَلَوْ شِئْتُ أَخْبَرْتُكُمْ بِالثَّالِثِ لَفَعَلْتُ ‏","","",""],[796,796,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ أَبِي مُزَاحِمٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الزَّيَّاتُ ‏ ‏حَدَّثَنِي ‏ ‏عَوْنُ بْنُ أَبِي جُحَيْفَةَ ‏ ‏قَالَ ‏ ‏كَانَ أَبِي مِنْ شُرَطِ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَكَانَ تَحْتَ الْمِنْبَرِ ‏ ‏فَحَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ صَعِدَ الْمِنْبَرَ ‏ ‏يَعْنِي ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَحَمِدَ اللَّهَ تَعَالَى وَأَثْنَى عَلَيْهِ وَصَلَّى عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏خَيْرُ هَذِهِ الْأُمَّةِ بَعْدَ نَبِيِّهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَالثَّانِي ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَقَالَ يَجْعَلُ اللَّهُ تَعَالَى الْخَيْرَ حَيْثُ أَحَبَّ ‏","","",""],[797,797,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَنْبَأَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا زَوَّجَهُ ‏ ‏فَاطِمَةَ ‏ ‏بَعَثَ مَعَهُ بِخَمِيلَةٍ وَوِسَادَةٍ مِنْ ‏ ‏أَدَمٍ ‏ ‏حَشْوُهَا لِيفٌ وَرَحَيَيْنِ وَسِقَاءٍ وَجَرَّتَيْنِ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏لِفَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏ذَاتَ يَوْمٍ وَاللَّهِ لَقَدْ ‏ ‏سَنَوْتُ ‏ ‏حَتَّى لَقَدْ ‏ ‏اشْتَكَيْتُ ‏ ‏صَدْرِي قَالَ وَقَدْ جَاءَ اللَّهُ أَبَاكِ ‏ ‏بِسَبْيٍ ‏ ‏فَاذْهَبِي فَاسْتَخْدِمِيهِ فَقَالَتْ وَأَنَا وَاللَّهِ قَدْ طَحَنْتُ حَتَّى ‏ ‏مَجَلَتْ ‏ ‏يَدَايَ فَأَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا جَاءَ بِكِ أَيْ بُنَيَّةُ قَالَتْ جِئْتُ لَأُسَلِّمَ عَلَيْكَ ‏ ‏وَاسْتَحْيَا أَنْ تَسْأَلَهُ وَرَجَعَتْ فَقَالَ مَا فَعَلْتِ قَالَتْ اسْتَحْيَيْتُ أَنْ أَسْأَلَهُ فَأَتَيْنَاهُ جَمِيعًا فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَا رَسُولَ اللَّهِ وَاللَّهِ لَقَدْ ‏ ‏سَنَوْتُ ‏ ‏حَتَّى ‏ ‏اشْتَكَيْتُ ‏ ‏صَدْرِي وَقَالَتْ ‏ ‏فَاطِمَةُ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَدْ طَحَنْتُ حَتَّى ‏ ‏مَجَلَتْ ‏ ‏يَدَايَ وَقَدْ جَاءَكَ اللَّهُ ‏ ‏بِسَبْيٍ ‏ ‏وَسَعَةٍ فَأَخْدِمْنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ لَا ‏ ‏أُعْطِيكُمَا وَأَدَعُ ‏ ‏أَهْلَ الصُّفَّةِ ‏ ‏تَطْوَ بُطُونُهُمْ لَا أَجِدُ مَا أُنْفِقُ عَلَيْهِمْ وَلَكِنِّي أَبِيعُهُمْ وَأُنْفِقُ عَلَيْهِمْ أَثْمَانَهُمْ فَرَجَعَا فَأَتَاهُمَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ دَخَلَا فِي قَطِيفَتِهِمَا إِذَا غَطَّتْ رُءُوسَهُمَا تَكَشَّفَتْ أَقْدَامُهُمَا وَإِذَا غَطَّيَا أَقْدَامَهُمَا تَكَشَّفَتْ رُءُوسُهُمَا فَثَارَا فَقَالَ مَكَانَكُمَا ثُمَّ قَالَ أَلَا أُخْبِرُكُمَا بِخَيْرٍ مِمَّا سَأَلْتُمَانِي قَالَا بَلَى فَقَالَ كَلِمَاتٌ ‏ ‏عَلَّمَنِيهِنَّ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ ‏ ‏تُسَبِّحَانِ فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ عَشْرًا ‏ ‏وَتَحْمَدَانِ عَشْرًا وَتُكَبِّرَانِ عَشْرًا وَإِذَا أَوَيْتُمَا إِلَى فِرَاشِكُمَا فَسَبِّحَا ثَلَاثًا وَثَلَاثِينَ وَاحْمَدَا ثَلَاثًا وَثَلَاثِينَ وَكَبِّرَا أَرْبَعًا وَثَلَاثِينَ ‏ ‏قَالَ فَوَاللَّهِ مَا تَرَكْتُهُنَّ مُنْذُ ‏ ‏عَلَّمَنِيهِنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ لَهُ ‏ ‏ابْنُ الْكَوَّاءِ ‏ ‏وَلَا لَيْلَةَ ‏ ‏صِفِّينَ ‏ ‏فَقَالَ قَاتَلَكُمْ اللَّهُ يَا أَهْلَ ‏ ‏الْعِرَاقِ ‏ ‏نَعَمْ وَلَا لَيْلَةَ ‏ ‏صِفِّينَ ‏","","",""],[798,798,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏جَلَدَ ‏ ‏شَرَاحَةَ ‏ ‏يَوْمَ الْخَمِيسِ ‏ ‏وَرَجَمَهَا ‏ ‏يَوْمَ الْجُمُعَةِ وَقَالَ أَجْلِدُهَا بِكِتَابِ اللَّهِ ‏ ‏وَأَرْجُمُهَا ‏ ‏بِسُنَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[799,799,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏أَنَا وَرَجُلَانِ رَجُلٌ مِنْ قَوْمِي وَرَجُلٌ مِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏أَحْسِبُ فَبَعَثَهُمَا وَجْهًا وَقَالَ أَمَا إِنَّكُمَا ‏ ‏عِلْجَانِ ‏ ‏فَعَالِجَا ‏ ‏عَنْ دِينِكُمَا ثُمَّ دَخَلَ ‏ ‏الْمَخْرَجَ ‏ ‏فَقَضَى حَاجَتَهُ ثُمَّ خَرَجَ فَأَخَذَ حَفْنَةً مِنْ مَاءٍ فَتَمَسَّحَ بِهَا ثُمَّ جَعَلَ يَقْرَأُ الْقُرْآنَ قَالَ فَكَأَنَّهُ رَآنَا أَنْكَرْنَا ذَلِكَ ثُمَّ قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْضِي ‏ ‏حَاجَتَهُ ثُمَّ يَخْرُجُ فَيَقْرَأُ الْقُرْآنَ وَيَأْكُلُ مَعَنَا اللَّحْمَ وَلَمْ يَكُنْ ‏ ‏يَحْجُبُهُ ‏ ‏عَنْ الْقُرْآنِ شَيْءٌ لَيْسَ الْجَنَابَةَ ‏","","",""],[800,800,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏شَاكِيًا ‏ ‏فَمَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أَقُولُ اللَّهُمَّ إِنْ كَانَ أَجَلِي قَدْ حَضَرَ فَأَرِحْنِي وَإِنْ كَانَ مُتَأَخِّرًا فَارْفَعْنِي وَإِنْ كَانَ ‏ ‏بَلَاءً ‏ ‏فَصَبِّرْنِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ قُلْتَ فَأَعَادَ عَلَيْهِ مَا قَالَ قَالَ فَضَرَبَهُ بِرِجْلِهِ وَقَالَ ‏ ‏اللَّهُمَّ عَافِهِ ‏ ‏أَوْ اللَّهُمَّ اشْفِهِ شَكَّ ‏ ‏شُعْبَةُ ‏ ‏قَالَ فَمَا ‏ ‏اشْتَكَيْتُ ‏ ‏وَجَعِي ذَاكَ بَعْدُ ‏","","",""]];
